// While the replay pane is open, the conversation moves into it as a phone
// chat, the way two colleagues message: the person's lines in green on the
// right, marked read; Claude's on the left under its mascot; a typing line
// while Claude works. The transcript's own rows step aside, so the pane holds
// the whole picture: the phone, and the work it talks about beside it.

import type { On } from 'claude-code'

import { cellWidth } from './cells'
import { words } from './i18n'
import type { Theme } from './themes'
import type { GitlogueChatLine } from '../types'

const CLAUDE = '#d77757'
const MINE = '#06c755'
const INK_ON_MINE = '#0a0a0a'
const THEIRS = 0x334455
const BAR = 0x2a3040
const FIELD = 0x3a4256
// Claude Code's mascot, as its welcome banner draws it.
const MASCOT = [' ▐▛███▜▌ ', '▝▜█████▛▘', '  ▘▘ ▝▝  ']
const AVATAR_WIDTH = 10

export type ChatLine = GitlogueChatLine

// How wide a bubble for `text` is: its longest line, within the room.
function bubbleWidth(text: string, room: number, isMarkdown: boolean): number {
  if (isMarkdown && /```|^\s*\|/m.test(text)) return room
  const longest = Math.max(1, ...text.split('\n').map(line => cellWidth(line.replace(/[*_`#>]/g, ''))))
  return Math.max(4, Math.min(room, longest + 2))
}

const two = (n: number) => String(n).padStart(2, '0')
const now = () => {
  const d = new Date()
  return `${two(d.getHours())}:${two(d.getMinutes())}`
}

// What a user row says to the person: the typed text, without the tags the
// engine wraps its own notes and commands in.
const spoken = (text: string) =>
  text
    .replace(/<(system-reminder|command-[\w-]+|local-command-[\w-]+|task-notification)>[\s\S]*?<\/\1>/g, '')
    .trim()

const LONGEST_MESSAGE = 4000

export class Chat {
  lines: ChatLine[] = []
  isWorking = false
  version = 0
  // Read back up the chat, the message standing on the phone's floor and how
  // many rows it has sunk below it; null follows the newest.
  floor: number | null = null
  lift = 0
  // The phone as last drawn, to measure scrolling against.
  view = { width: 60, rows: 20 }

  // About how many rows a line takes in the phone, bubble edges and spacing
  // included: its text wrapped at its bubble's width.
  rowsOf(line: ChatLine, index: number): number {
    const room = this.view.width - 2
    const inner = line.role === 'me' ? Math.floor(room * 0.75) - 2 : room - AVATAR_WIDTH - 10
    const wrapped = line.text
      .split('\n')
      .reduce((n, text) => n + Math.max(1, Math.ceil(cellWidth(text) / Math.max(8, inner))), 0)
    const first = line.role === 'claude' && this.lines[index - 1]?.role !== 'claude'
    return wrapped + 2 + (line.role === 'me' ? 1 : first ? 2 : 0)
  }

  // Sinks the messages by `rows`, bringing older ones into view (newer ones
  // when negative). Rows are only measured around the message on the floor,
  // so the oldest is as reachable as the newest however long the chat.
  scrollBy(rows: number) {
    const last = this.lines.length - 1
    if (last < 0) return
    const rowsAt = (i: number) => this.rowsOf(this.lines[i]!, i)
    let at = this.floor ?? last
    let lift = this.lift + rows
    while (at > 0 && lift >= rowsAt(at)) lift -= rowsAt(at--)
    while (lift < 0 && at < last) lift += rowsAt(++at)
    // The oldest message stops a little below the top of the phone.
    const room = this.view.rows - 2 - Math.floor(this.view.rows / 3)
    let above = -lift
    for (let i = 0; i <= at && above < room; i++) above += rowsAt(i)
    if (above < room) {
      lift -= room - above
      while (lift < 0 && at < last) lift += rowsAt(++at)
    }
    const floor = at === last && lift <= 0 ? null : at
    lift = floor === null ? 0 : lift
    if (floor === this.floor && lift === this.lift) return
    this.floor = floor
    this.lift = lift
    this.version++
  }

  // Back to the newest, then `rows` up from it.
  scrollTo(rows: number) {
    this.floor = null
    this.lift = 0
    this.version++
    this.scrollBy(rows)
  }

  add(line: ChatLine) {
    if (!line.text.trim()) return
    // The terminal draws no text longer than 10000 characters in one piece.
    if (line.text.length > LONGEST_MESSAGE) line = { ...line, text: line.text.slice(0, LONGEST_MESSAGE) + '…' }
    // Read back up the chat, the view stays on its floor as new lines come.
    this.lines.push(line)
    this.version++
  }

  // The chat as it was kept, word for word: it outlives a compacted
  // conversation, whose earlier messages the session no longer holds.
  restore(lines: readonly ChatLine[]) {
    this.lines = [...lines]
    this.floor = null
    this.lift = 0
    this.version++
  }

  // The conversation so far, for a session with no kept chat, so the phone
  // opens on it.
  load(messages: readonly { role: 'user' | 'assistant'; text: string }[]) {
    this.lines = []
    this.floor = null
    this.lift = 0
    for (const message of messages) {
      // A compacted conversation's summary is no one's message.
      if (message.role === 'user' && message.text.startsWith('This session is being continued from a previous conversation')) continue
      const text = message.role === 'user' ? spoken(message.text) : message.text.trim()
      if (text) this.add({ role: message.role === 'user' ? 'me' : 'claude', text, isRead: true })
    }
  }

  // The oldest of the person's lines still on its way has reached Claude.
  markRead() {
    const line = this.lines.find(other => other.role === 'me' && !other.isRead)
    if (!line) return
    line.isRead = true
    this.version++
  }

  working(isWorking: boolean) {
    if (this.isWorking === isWorking) return
    this.isWorking = isWorking
    this.version++
  }
}

// The phone: a top bar, the latest messages filling up from the bottom (the
// oldest cut off above, as a chat scrolled to its end), and the input bar.
export function drawPhone(
  el: { Box: any; Text: any; Markdown: any },
  chat: Chat,
  theme: Theme,
  hex: (color: number) => string,
  width: number,
  height: number,
) {
  const { Box, Text, Markdown } = el
  chat.view = { width, rows: Math.max(1, height - 2) }
  const screen = hex(theme.backgroundLeft)
  const bar = hex(BAR)
  const room = width - 2
  // Only what the phone shows, and a screen more above it, is laid out: the
  // whole conversation would be laid out again on every frame.
  const floor = chat.floor ?? chat.lines.length - 1
  let start = floor + 1
  for (let left = chat.lift + 2 * chat.view.rows; start > 0 && left > 0; ) {
    start--
    left -= chat.rowsOf(chat.lines[start]!, start)
  }
  const messages = chat.lines.slice(start, floor + 1).map((line, i) => {
    if (line.role === 'me') {
      const bubble = bubbleWidth(line.text, Math.floor(room * 0.75), false)
      return (
        <Box flexDirection="row" justifyContent="flex-end" alignItems="flex-end" marginTop={1} flexShrink={0}>
          <Box flexDirection="column" alignItems="flex-end" marginRight={1}>
            {line.isRead && <Text dimColor>{words.read}</Text>}
            {line.time && <Text dimColor>{line.time}</Text>}
          </Box>
          <Box flexDirection="column" width={bubble}>
            <Text color={MINE}>{'▗' + '▄'.repeat(bubble - 2) + '▖'}</Text>
            <Box width={bubble} paddingX={1} backgroundColor={MINE}>
              <Text color={INK_ON_MINE}>{line.text}</Text>
            </Box>
            <Text color={MINE}>{'▝' + '▀'.repeat(bubble - 2) + '▘'}</Text>
          </Box>
          <Box flexDirection="column" width={1} alignSelf="flex-start">
            <Text> </Text>
            <Text color={MINE}>◥</Text>
          </Box>
        </Box>
      )
    }
    const first = chat.lines[start + i - 1]?.role !== 'claude'
    const fill = hex(THEIRS)
    const bubble = bubbleWidth(line.text, room - AVATAR_WIDTH - 8, true)
    return (
      <Box flexDirection="row" marginTop={first ? 1 : 0} flexShrink={0}>
        <Box width={AVATAR_WIDTH} flexDirection="column">
          {first && MASCOT.map(row => <Text color={CLAUDE}>{row}</Text>)}
        </Box>
        <Box flexDirection="column">
          {first && <Text dimColor>Claude</Text>}
          <Box flexDirection="row" alignItems="flex-end">
            <Box flexDirection="column" width={1} alignSelf="flex-start">
              <Text> </Text>
              <Text color={fill}>{first ? '◤' : ' '}</Text>
            </Box>
            <Box flexDirection="column" width={bubble}>
              <Text color={fill}>{'▗' + '▄'.repeat(bubble - 2) + '▖'}</Text>
              <Box width={bubble} paddingX={1} backgroundColor={fill}>
                <Markdown text={line.text.slice(0, 9000)} />
              </Box>
              <Text color={fill}>{'▝' + '▀'.repeat(bubble - 2) + '▘'}</Text>
            </Box>
            {line.time && (
              <Box marginLeft={1}>
                <Text dimColor>{line.time}</Text>
              </Box>
            )}
          </Box>
        </Box>
      </Box>
    )
  })
  if (chat.isWorking)
    messages.push(
      <Box flexDirection="row" marginTop={1} flexShrink={0} alignItems="center">
        <Box width={AVATAR_WIDTH} flexDirection="column">
          {MASCOT.map(row => <Text color={CLAUDE}>{row}</Text>)}
        </Box>
        <Box paddingX={1} backgroundColor={hex(THEIRS)}>
          <Text>···</Text>
        </Box>
        <Text dimColor> {words.typing}</Text>
      </Box>,
    )

  return (
    <Box width={width} height={height} flexDirection="column" backgroundColor={screen}>
      <Box width={width} backgroundColor={bar} paddingX={1} flexDirection="row" flexShrink={0}>
        <Text dimColor>‹ </Text>
        <Text bold>Claude</Text>
        <Box flexGrow={1} />
        <Text dimColor>☏ ≡</Text>
      </Box>
      <Box flexGrow={1} flexDirection="column" justifyContent="flex-end" overflow="hidden" paddingX={1}>
        {/* The messages stand on the phone's floor; scrolled, the one on the
            floor sinks below it, bringing older ones down into view. */}
        <Box flexDirection="column" flexShrink={0} marginBottom={-chat.lift}>
          {messages}
        </Box>
        {chat.floor !== null && (
          <Box position="absolute" bottom={0} left={0} width={width} justifyContent="center">
            <Box backgroundColor={bar} paddingX={1}>
              <Text dimColor>{words.backToLatest}</Text>
            </Box>
          </Box>
        )}
      </Box>
      <Box width={width} backgroundColor={bar} flexDirection="row" paddingX={1} flexShrink={0}>
        <Text dimColor>＋ ◎ ▣ </Text>
        <Box flexGrow={1} backgroundColor={hex(FIELD)} paddingX={1}>
          <Text dimColor>Aa</Text>
        </Box>
        <Text dimColor> ☺ ♪</Text>
      </Box>
    </Box>
  )
}

export function registerChat(on: On, ctx: { isOn: () => boolean; chat: Chat }) {
  const { chat } = ctx

  // What the person sends, at once, idle or mid-turn.
  on('prompt.submit', ($, e, next) => {
    if (e.origin.kind === 'composer' || e.origin.kind === 'bridge') {
      const images = e.attachments?.length ? ` ${words.images(e.attachments.length)}` : ''
      chat.add({ role: 'me', text: e.text.trim() + images, time: now(), isRead: false })
      $.ui.invalidate('ui.render')
    }
    return next(e)
  })

  // Each block of Claude's reply as it is stored; and the person's prompts as
  // they reach the conversation, idle or folded into a running turn, which is
  // when they are read.
  on('session.append', async ($, e, next) => {
    const stored = await next(e)
    const sender = (e.origin as { kind?: string }).kind
    if (
      (e.door === 'prompt' || e.door === 'delivery') &&
      e.agentId === undefined &&
      e.message.role === 'user' &&
      !e.message.isMeta &&
      (sender === 'composer' || sender === 'bridge')
    ) {
      chat.markRead()
      $.ui.invalidate('ui.render')
    }
    if (e.door === 'response' && e.agentId === undefined && e.message.role === 'assistant') {
      const text = e.message.content
        .flatMap(block => (block.type === 'text' && typeof block.text === 'string' ? [block.text] : []))
        .join('\n')
        .trim()
      if (text) {
        chat.add({ role: 'claude', text, time: now() })
        $.ui.invalidate('ui.render')
      }
    }
    return stored
  })

  // Whether Claude is at work, as the band over the prompt knows it: right
  // even when the mod loaded in the middle of a turn.
  on('ui.render', { component: 'AbovePrompt' }, ($, e, next) => {
    chat.working(e.props.isWorking)
    return next(e)
  })

  // The transcript's own rows step aside while the phone holds the conversation.
  on('ui.render', { component: 'UserMessage' }, ($, e, next) => {
    if (!ctx.isOn() || e.props.isExpanded || e.surface !== 'terminal') return next(e)
    const { Box } = $.ui.resolve(e)
    return <Box display="none" />
  })
  on('ui.render', { component: 'AssistantMessage' }, ($, e, next) => {
    if (!ctx.isOn() || e.surface !== 'terminal') return next(e)
    const { Box } = $.ui.resolve(e)
    return <Box display="none" />
  })
  on('ui.render', { component: 'Spinner' }, ($, e, next) => {
    if (!ctx.isOn() || e.surface !== 'terminal') return next(e)
    const { Box } = $.ui.resolve(e)
    return <Box display="none" />
  })
  on('ui.render', { component: 'InfoNotice' }, ($, e, next) => {
    if (!ctx.isOn() || e.surface !== 'terminal') return next(e)
    const { Box } = $.ui.resolve(e)
    return <Box display="none" />
  })
  on('ui.render', { component: 'ToolUse' }, ($, e, next) => {
    if (!ctx.isOn() || e.surface !== 'terminal') return next(e)
    const { Box } = $.ui.resolve(e)
    return <Box display="none" />
  })
  on('ui.render', { component: 'ToolResult' }, ($, e, next) => {
    if (!ctx.isOn() || e.surface !== 'terminal') return next(e)
    const { Box } = $.ui.resolve(e)
    return <Box display="none" />
  })
  on('ui.render', { component: 'ToolProgress' }, ($, e, next) => {
    if (!ctx.isOn() || e.surface !== 'terminal') return next(e)
    const { Box } = $.ui.resolve(e)
    return <Box display="none" />
  })
  on('ui.render', { component: 'ToolGroup' }, ($, e, next) => {
    if (!ctx.isOn() || e.props.isExpanded || e.surface !== 'terminal') return next(e)
    const { Box } = $.ui.resolve(e)
    return <Box display="none" />
  })
}

files.hooks/frame.ts:
// Paints the player's state as gitlogue lays it out: file tree over turn info
// on the left (30%), editor over terminal on the right (70%), an Open File
// dialog over the middle. Cells are packed as Raster cells: [codePoint, fg, bg].

import { cellWidth, isWide, TAIL } from './cells'
import { words } from './i18n'
import { Tok } from './highlight'
import type { FileEntry, Player } from './player'
import type { Theme } from './themes'

export const DEFAULT_COLOR = 0x01000000

export type Layout = {
  width: number
  height: number
  leftWidth: number
  rightWidth: number
  // Rows of the upper panes (tree, editor); the separator follows when there is a lower one.
  topRows: number
  bottomRows: number
}

export function layoutFor(width: number, height: number): Layout {
  const leftWidth = width >= 72 ? Math.floor(width * 0.3) : 0
  const hasBottom = height >= 12
  const topRows = hasBottom ? Math.round((height - 1) * 0.8) : height
  return {
    width,
    height,
    leftWidth,
    rightWidth: width - leftWidth,
    topRows,
    bottomRows: hasBottom ? height - topRows - 1 : 0,
  }
}

// Wide characters drawn over the Raster, which holds narrow ones only: each
// run starts at a cell and covers two cells a character.
export type WideRun = { x: number; y: number; text: string; fg: number; bg: number }

export class Canvas {
  readonly width: number
  readonly height: number
  readonly cells: Uint32Array
  // The wide characters by the cell they start at; the Raster has blanks there.
  readonly wide = new Map<number, string>()

  constructor(width: number, height: number) {
    this.width = width
    this.height = height
    this.cells = new Uint32Array(width * height * 3)
    for (let i = 0; i < this.cells.length; i += 3) {
      this.cells[i] = 0x20
      this.cells[i + 1] = DEFAULT_COLOR
      this.cells[i + 2] = DEFAULT_COLOR
    }
  }

  set(x: number, y: number, ch: string, fg: number, bg: number) {
    if (x < 0 || y < 0 || x >= this.width || y >= this.height) return
    const at = y * this.width + x
    const i = at * 3
    const code = ch.charCodeAt(0)
    this.wide.delete(at)
    if (code >= 0xdc00 && code <= 0xdfff) {
      // The second half of a character past the BMP completes the first.
      const head = this.wide.get(at - 1)
      if (head?.length === 1 && x > 0) this.wide.set(at - 1, head + ch[0])
      this.cells[i] = 0x20
    } else if ((code >= 0xd800 && code <= 0xdbff) || isWide(code)) {
      this.wide.set(at, ch.length > 1 && code >= 0xd800 ? ch.slice(0, 2) : ch[0])
      this.cells[i] = 0x20
    } else this.cells[i] = ch === TAIL ? 0x20 : code
    this.cells[i + 1] = fg
    this.cells[i + 2] = bg
  }

  fill(x: number, y: number, w: number, h: number, bg: number) {
    for (let row = y; row < y + h; row++) for (let col = x; col < x + w; col++) this.set(col, row, ' ', bg, bg)
  }

  background(x: number, y: number, w: number, bg: number) {
    if (y < 0 || y >= this.height) return
    for (let col = Math.max(0, x); col < Math.min(this.width, x + w); col++) this.cells[(y * this.width + col) * 3 + 2] = bg
  }

  // Writes text from (x, y), cut at `maxX`; returns where it stopped. A wide
  // character takes two cells, and one that would be cut leaves a blank.
  text(x: number, y: number, s: string, fg: number, bg: number, maxX = this.width): number {
    for (let i = 0; i < s.length && x < maxX; i++) {
      const code = s.charCodeAt(i)
      const isPair = code >= 0xd800 && code <= 0xdbff && i + 1 < s.length
      if (!isPair && !isWide(code)) {
        this.set(x++, y, s[i], fg, bg)
        continue
      }
      if (x + 1 >= maxX) {
        this.set(x++, y, ' ', fg, bg)
        break
      }
      this.set(x++, y, s[i], fg, bg)
      this.set(x++, y, isPair ? s[++i] : TAIL, fg, bg)
      if (!isPair && s[i + 1] === TAIL) i++
    }
    return x
  }

  // The wide characters within one rectangle, from its corner, as runs of
  // one color each.
  wideRuns(x: number, y: number, w: number, h: number): WideRun[] {
    const runs: WideRun[] = []
    const heads = [...this.wide.keys()].sort((a, b) => a - b)
    for (const at of heads) {
      const col = at % this.width
      const row = Math.floor(at / this.width)
      const text = this.wide.get(at)!
      if (row < y || row >= y + h || col < x || col + 1 >= x + w) continue
      if (text.length === 1 && text.charCodeAt(0) >= 0xd800 && text.charCodeAt(0) <= 0xdbff) continue
      const fg = this.cells[at * 3 + 1]
      const bg = this.cells[at * 3 + 2]
      const last = runs[runs.length - 1]
      if (last && last.y === row - y && last.x + 2 * [...last.text].length === col - x && last.fg === fg && last.bg === bg) last.text += text
      else runs.push({ x: col - x, y: row - y, text, fg, bg })
    }
    return runs
  }

  // The cells of one rectangle, base64 as a Raster takes them.
  encode(x: number, y: number, w: number, h: number): string {
    const out = new Uint32Array(w * h * 3)
    for (let row = 0; row < h; row++) {
      const from = ((y + row) * this.width + x) * 3
      out.set(this.cells.subarray(from, from + w * 3), row * w * 3)
    }
    return toBase64(new Uint8Array(out.buffer))
  }
}

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

function toBase64(bytes: Uint8Array): string {
  const parts: string[] = []
  let chunk = ''
  let i = 0
  for (; i + 2 < bytes.length; i += 3) {
    const n = (bytes[i] << 16) | (bytes[i + 1] << 8) | bytes[i + 2]
    chunk += B64[(n >> 18) & 63] + B64[(n >> 12) & 63] + B64[(n >> 6) & 63] + B64[n & 63]
    if (chunk.length >= 8192) {
      parts.push(chunk)
      chunk = ''
    }
  }
  const rest = bytes.length - i
  if (rest === 1) {
    const n = bytes[i] << 16
    chunk += B64[(n >> 18) & 63] + B64[(n >> 12) & 63] + '=='
  } else if (rest === 2) {
    const n = (bytes[i] << 16) | (bytes[i + 1] << 8)
    chunk += B64[(n >> 18) & 63] + B64[(n >> 12) & 63] + B64[(n >> 6) & 63] + '='
  }
  parts.push(chunk)
  return parts.join('')
}

const MARKER = 0xffd75f

// `a` laid over `b` at `share` of its strength.
function mix(a: number, b: number, share: number): number {
  const channel = (shift: number) => Math.round(((a >> shift) & 255) * share + ((b >> shift) & 255) * (1 - share)) << shift
  return channel(16) | channel(8) | channel(0)
}

// Fades a color toward the background, as gitlogue dims rows away from the cursor.
function fade(fg: number, bg: number, distance: number): number {
  if (distance <= 0 || fg === DEFAULT_COLOR || bg === DEFAULT_COLOR) return fg
  const opacity = 1 - (Math.min(distance, 20) / 20) * 0.4
  const mix = (shift: number) =>
    Math.round(((fg >> shift) & 255) * opacity + ((bg >> shift) & 255) * (1 - opacity)) << shift
  return mix(16) | mix(8) | mix(0)
}

function tokenColor(theme: Theme, tok: number): number {
  switch (tok) {
    case Tok.Keyword:
      return theme.syntaxKeyword
    case Tok.Type:
      return theme.syntaxType
    case Tok.Function:
      return theme.syntaxFunction
    case Tok.String:
      return theme.syntaxString
    case Tok.Number:
      return theme.syntaxNumber
    case Tok.Comment:
      return theme.syntaxComment
    case Tok.Operator:
      return theme.syntaxOperator
    case Tok.Punctuation:
      return theme.syntaxPunctuation
    case Tok.Constant:
      return theme.syntaxConstant
    case Tok.Parameter:
      return theme.syntaxParameter
    case Tok.Property:
      return theme.syntaxProperty
    case Tok.Label:
      return theme.syntaxLabel
    default:
      return theme.syntaxVariable
  }
}

type Box = { x: number; y: number; w: number; h: number }

// The inside of a pane after gitlogue's padding: one row top and bottom, two columns each side.
function inner(box: Box): Box {
  const padY = box.h >= 3 ? 1 : 0
  const padX = box.w >= 12 ? 2 : 0
  return { x: box.x + padX, y: box.y + padY, w: box.w - 2 * padX, h: box.h - 2 * padY }
}

export function paint(player: Player, theme: Theme, layout: Layout, cursorOn: boolean): Canvas {
  const canvas = new Canvas(layout.width, layout.height)
  const { leftWidth, rightWidth, topRows, bottomRows } = layout
  if (leftWidth > 0) {
    paintTree(canvas, player, theme, { x: 0, y: 0, w: leftWidth, h: topRows })
    if (bottomRows > 0) {
      canvas.text(0, topRows, '─'.repeat(leftWidth), theme.separator, theme.backgroundLeft)
      canvas.fill(0, topRows + 1, leftWidth, bottomRows, theme.backgroundLeft)
    }
  }
  const editorBox = { x: leftWidth, y: 0, w: rightWidth, h: topRows }
  if (player.screen === 'browser') paintBrowser(canvas, player, theme, editorBox, cursorOn)
  else if (player.screen === 'image' && player.image) paintViewer(canvas, player, theme, editorBox)
  else if (player.screen === 'cast' && player.cast) paintCast(canvas, player, theme, editorBox)
  else paintEditor(canvas, player, theme, editorBox, cursorOn)
  if (bottomRows > 0) {
    canvas.text(leftWidth, topRows, '─'.repeat(rightWidth), theme.separator, theme.backgroundRight)
    paintTerminal(canvas, player, theme, { x: leftWidth, y: topRows + 1, w: rightWidth, h: bottomRows }, cursorOn)
  }
  if (player.dialog) paintDialog(canvas, player.dialog, theme)
  if (player.palette) paintPalette(canvas, player, theme, cursorOn)
  return canvas
}

function paintEditor(canvas: Canvas, player: Player, theme: Theme, box: Box, cursorOn: boolean) {
  const bg = theme.backgroundRight
  canvas.fill(box.x, box.y, box.w, box.h, bg)
  const area = inner(box)
  if (area.w <= 0 || area.h <= 0) return

  if (!player.hasFile) {
    const message = player.turn ? words.waitingEdit : words.waiting
    const x = area.x + Math.max(0, Math.floor((area.w - cellWidth(message)) / 2))
    canvas.text(x, area.y + Math.floor(area.h / 2), message, theme.statusNoCommit, bg, area.x + area.w)
    return
  }

  const lines = player.lines
  const numberWidth = Math.max(3, String(lines.length).length)
  const gutter = numberWidth + 1 + 2
  const textWidth = Math.max(1, area.w - gutter)
  const rowsOf = (line: string) => Math.max(1, Math.ceil(line.length / textWidth))

  // Keep the cursor's row in the middle, as gitlogue scrolls.
  let cursorRow = 0
  let total = 0
  for (let i = 0; i < lines.length; i++) {
    if (i === player.cursorLine) cursorRow = total + Math.min(rowsOf(lines[i]) - 1, Math.floor(player.cursorCol / textWidth))
    total += rowsOf(lines[i])
  }
  const half = Math.floor(area.h / 2)
  const top =
    cursorRow < half ? 0 : cursorRow + half >= total ? Math.max(0, total - area.h) : cursorRow - half

  let index = 0
  let skipped = 0
  while (index < lines.length && skipped + rowsOf(lines[index]) <= top) skipped += rowsOf(lines[index++])
  let sub = top - skipped

  const showCursor = cursorOn && player.active === 'editor'
  for (let row = 0; row < area.h && index < lines.length; row++) {
    const y = area.y + row
    const line = lines[index]
    const isCursorLine = index === player.cursorLine
    const rowBg = isCursorLine ? theme.editorCursorLineBg : bg
    const distance = Math.abs(index - player.cursorLine)
    if (isCursorLine) canvas.background(box.x, y, box.w, rowBg)

    if (sub === 0) {
      const number = String(index + 1).padStart(numberWidth) + ' '
      const color = isCursorLine ? theme.editorLineNumberCursor : fade(theme.editorLineNumber, rowBg, distance)
      canvas.text(area.x, y, number, color, rowBg)
    }

    const toks = player.highlighter.line(lines, index)
    const from = sub * textWidth
    const to = Math.min(line.length, from + textWidth)
    const x0 = area.x + gutter
    // The highlighter: over the text of each line read, from its first word.
    const marks = player.marks
    const markEnd =
      !marks || index < marks.from || index > marks.line ? 0 : index < marks.line ? line.length : marks.col
    const markStart = line.length - line.trimStart().length
    for (let col = from; col < to; col++) {
      const isMarked = col >= markStart && col < markEnd
      const cellBg = isMarked ? mix(MARKER, rowBg, 0.34) : rowBg
      canvas.set(x0 + col - from, y, line[col], fade(tokenColor(theme, toks[col]), cellBg, isMarked ? 0 : distance), cellBg)
    }

    if (isCursorLine && showCursor) {
      const isLastRow = sub === rowsOf(line) - 1
      const col = player.cursorCol
      if ((col >= from && col < from + textWidth) || (isLastRow && col >= from)) {
        const x = x0 + Math.min(col - from, textWidth - 1)
        canvas.set(x, y, line[col] ?? ' ', theme.editorCursorCharFg, theme.editorCursorCharBg)
      }
    }

    if (++sub >= rowsOf(line)) {
      sub = 0
      index++
    }
  }
}

// The workspace as a file explorer: folders open along the paths Claude has
// walked, the selection where it last went, and each changed file marked with
// its counts; files the current turn has not touched recede.
function paintExplorer(canvas: Canvas, player: Player, theme: Theme, area: Box) {
  const bg = theme.backgroundLeft
  const changed = new Map<string, FileEntry>()
  for (const entry of player.files.values()) if (entry.file) changed.set(entry.file, entry)
  const rows = player.explorer.rows(new Set(changed.keys()))
  const selected = rows.findIndex(row => row.path === player.explorer.selected)
  const offset =
    selected >= area.h ? Math.min(selected - Math.floor(area.h / 2), rows.length - area.h) : 0
  const turn = player.turn?.id
  const maxX = area.x + area.w
  const hasChanges = (dir: string) => [...changed.keys()].some(path => path.startsWith(dir + '/'))

  for (let r = 0; r < area.h && offset + r < rows.length; r++) {
    const index = offset + r
    const row = rows[index]
    const y = area.y + r
    const isSelected = index === selected
    const rowBg = isSelected ? theme.fileTreeCurrentFileBg : bg
    if (isSelected) canvas.background(area.x, y, area.w, rowBg)
    const entry = changed.get(row.path)
    const isPast = entry ? turn !== undefined && entry.turn !== turn : row.kind === 'file'
    const distance = Math.max(selected < 0 ? 0 : Math.abs(index - selected), isPast ? 12 : 0)
    const dim = (color: number) => fade(color, rowBg, distance)
    let x = area.x + row.depth * 2
    const put = (text: string, color: number) => (x = canvas.text(x, y, text, dim(color), rowBg, maxX))

    switch (row.kind) {
      case 'root':
      case 'dir': {
        put(row.isOpen ? '▾ ' : '▸ ', theme.separator)
        const color = hasChanges(row.path) ? theme.fileTreeModified : theme.fileTreeDirectory
        put(row.name + (row.kind === 'dir' ? '/' : ''), row.kind === 'root' ? theme.fileTreeCurrentFileFg : color)
        break
      }
      case 'more':
        put('  ' + row.name, theme.separator)
        break
      case 'file':
        if (!entry) {
          put('  ' + row.name, theme.fileTreeDefault)
          break
        }
        if (entry.committed) {
          put('✓ ' + row.name, theme.editorLineNumber)
          break
        }
        if (player.flight && row.path === player.explorer.selected) {
          put('  ' + row.name, theme.separator)
          break
        }
        put(entry.status + ' ', entry.status === '+' ? theme.fileTreeAdded : theme.fileTreeModified)
        put(row.name, isSelected ? theme.fileTreeCurrentFileFg : theme.fileTreeDefault)
        if (entry.note) {
          put(' ' + entry.note, theme.editorLineNumber)
          break
        }
        put(` +${entry.added}`, theme.fileTreeStatsAdded)
        put(` -${entry.deleted}`, theme.fileTreeStatsDeleted)
        break
    }
  }
  paintTrash(canvas, player, theme, area, offset)
}

// Where the picture sits in the image viewer, in cells of the right column:
// as large as the area allows, at the picture's own proportions (a cell is
// about twice as tall as it is wide), centred.
export function imageBox(layout: Layout, image: { width: number; height: number }) {
  const area = inner({ x: 0, y: 0, w: layout.rightWidth, h: layout.topRows })
  const top = area.y + 2
  const room = { columns: Math.min(255, area.w), rows: Math.min(255, area.h - 2) }
  if (room.columns < 2 || room.rows < 2 || image.width < 1 || image.height < 1) return undefined
  let columns = room.columns
  let rows = Math.round((columns * image.height) / image.width / 2)
  if (rows > room.rows) {
    rows = room.rows
    columns = Math.min(room.columns, Math.round((rows * 2 * image.width) / image.height))
  }
  columns = Math.max(1, columns)
  rows = Math.max(1, rows)
  return {
    left: area.x + Math.floor((room.columns - columns) / 2),
    top: top + Math.floor((room.rows - rows) / 2),
    columns,
    rows,
  }
}

// The picture's frame: its name and size above; the picture itself is laid
// over the empty area by the pane's drawing.
function paintViewer(canvas: Canvas, player: Player, theme: Theme, box: Box) {
  const bg = theme.backgroundRight
  canvas.fill(box.x, box.y, box.w, box.h, bg)
  const area = inner(box)
  const image = player.image
  if (!image || area.w <= 0 || area.h <= 0) return
  let x = canvas.text(area.x, area.y, '▣ ', theme.fileTreeModified, bg)
  x = canvas.text(x, area.y, image.path, theme.fileTreeCurrentFileFg, bg, area.x + area.w)
  canvas.text(x, area.y, `  ${image.width}×${image.height}`, theme.editorLineNumber, bg, area.x + area.w)
  canvas.text(area.x, area.y + 1, '─'.repeat(area.w), theme.separator, bg)
}

// A recording of one of Claude's screens: which screen, its size and the
// speed it plays at above; the frames themselves are laid over by the pane.
function paintCast(canvas: Canvas, player: Player, theme: Theme, box: Box) {
  const bg = theme.backgroundRight
  canvas.fill(box.x, box.y, box.w, box.h, bg)
  const area = inner(box)
  const cast = player.cast
  if (!cast || area.w <= 0 || area.h <= 0) return
  let x = canvas.text(area.x, area.y, '● ', theme.fileTreeDeleted, bg)
  x = canvas.text(x, area.y, words.screen(cast.screen), theme.fileTreeCurrentFileFg, bg, area.x + area.w)
  canvas.text(x, area.y, `  ${cast.width}×${cast.height}  ×${cast.speed}`, theme.editorLineNumber, bg, area.x + area.w)
  canvas.text(area.x, area.y + 1, '─'.repeat(area.w), theme.separator, bg)
}

const SEARCH_MARK: [string, number][] = [
  ['G', 0x4285f4],
  ['o', 0xea4335],
  ['o', 0xfbbc05],
  ['g', 0x4285f4],
  ['l', 0x34a853],
  ['e', 0xea4335],
]

// The editor's area as a browser: the address bar and the line that fills as
// a page loads, over a search page, its results, or the page being read.
function paintBrowser(canvas: Canvas, player: Player, theme: Theme, box: Box, cursorOn: boolean) {
  const bg = theme.backgroundRight
  canvas.fill(box.x, box.y, box.w, box.h, bg)
  const area = inner(box)
  if (area.w < 12 || area.h < 4) return
  const b = player.browser
  const maxX = area.x + area.w
  const typing = cursorOn && player.active === 'explorer'
  const bar = theme.editorCursorLineBg

  // The address bar.
  let x = canvas.text(area.x, area.y, '‹ › ⟳ ', theme.separator, bg)
  canvas.background(x, area.y, maxX - x, bar)
  x = canvas.text(x, area.y, ' ⌕ ', theme.editorLineNumber, bar)
  const room = maxX - x - 2
  const url = b.url.length > room ? '…' + b.url.slice(b.url.length - room + 1) : b.url
  x = canvas.text(x, area.y, url, theme.fileTreeCurrentFileFg, bar, maxX)
  if (typing && b.focus === 'address') canvas.set(Math.min(x, maxX - 1), area.y, ' ', theme.editorCursorCharFg, theme.editorCursorCharBg)

  // The load line under it.
  const filled = Math.round(area.w * b.loading)
  for (let i = 0; i < area.w; i++)
    canvas.set(area.x + i, area.y + 1, b.loading < 1 && i < filled ? '━' : '─', b.loading < 1 && i < filled ? theme.editorCursorCharBg : theme.separator, bg)

  const top = area.y + 2
  const rows = area.h - 2
  const mark = (mx: number, y: number, spaced: boolean) => {
    for (const [ch, color] of SEARCH_MARK) {
      canvas.set(mx, y, ch, color, bg)
      mx += spaced ? 2 : 1
    }
    return mx
  }

  if (b.page === 'home') {
    const width = Math.min(area.w - 4, 64)
    const left = area.x + Math.floor((area.w - width) / 2)
    const y = top + Math.max(0, Math.floor(rows / 2) - 4)
    mark(area.x + Math.floor((area.w - 11) / 2), y, true)
    searchBox(canvas, theme, left, y + 2, width, b.query, typing && b.focus === 'box', bg)
    const buttons = words.googleButtons
    canvas.text(area.x + Math.max(0, Math.floor((area.w - buttons.length) / 2)), y + 6, buttons, theme.editorLineNumber, bg, maxX)
    return
  }

  if (b.page === 'results') {
    let mx = mark(area.x, top, false)
    mx += 2
    canvas.background(mx, top, Math.min(maxX - mx, Math.max(20, b.query.length + 6)), bar)
    canvas.text(mx + 1, top, '⌕ ' + b.query, theme.fileTreeCurrentFileFg, bar, maxX)
    canvas.text(area.x, top + 1, b.loading < 1 ? '' : b.stats, theme.editorLineNumber, bg, maxX)
    const per = 3
    const first = Math.max(0, Math.min(b.selected - Math.floor((rows - 3) / per / 2), b.shown - Math.floor((rows - 3) / per)))
    for (let i = first, y = top + 3; i < b.shown && y + 1 < top + rows; i++, y += per) {
      const link = b.results[i]
      const isSelected = i === b.selected
      const rowBg = isSelected ? bar : bg
      if (isSelected) {
        canvas.background(area.x, y, area.w, rowBg)
        canvas.background(area.x, y + 1, area.w, rowBg)
      }
      const host = link.url.replace(/^https?:\/\//, '')
      canvas.text(area.x + 2, y, host.length > area.w - 2 ? host.slice(0, area.w - 3) + '…' : host, theme.statusAuthor, rowBg, maxX)
      canvas.text(area.x + 2, y + 1, link.title.length > area.w - 2 ? link.title.slice(0, area.w - 3) + '…' : link.title, theme.syntaxFunction, rowBg, maxX)
      if (isSelected) canvas.set(area.x, y + 1, '▸', theme.editorCursorCharBg, rowBg)
    }
    return
  }

  // A page being read: its address as the title, the text wrapped, the line
  // being read a third of the way down and the rest receding from it.
  canvas.text(area.x, top, b.url.replace(/\/.*$/, ''), theme.statusHash, bg, maxX)
  const wrapped: { text: string; source: number }[] = []
  // Wrapped at spaces, as a page reflows; a word longer than a line is cut.
  b.body.forEach((line, source) => {
    if (line.length === 0) wrapped.push({ text: '', source })
    let rest = line
    while (rest.length > 0) {
      let cut = rest.length <= area.w ? rest.length : rest.lastIndexOf(' ', area.w)
      if (cut <= 0) cut = Math.min(area.w, rest.length)
      wrapped.push({ text: rest.slice(0, cut), source })
      rest = rest.slice(cut).replace(/^ /, '')
    }
  })
  const start = wrapped.findIndex(row => row.source >= b.scroll)
  const view = rows - 2
  const reading = Math.floor(view / 3)
  const from = Math.max(0, (start < 0 ? wrapped.length : start) - reading)
  let inFence = false
  for (let i = 0; i < from; i++) if (/^\s*```/.test(wrapped[i].text)) inFence = !inFence
  for (let r = 0; r < view && from + r < wrapped.length; r++) {
    const row = wrapped[from + r]
    const y = top + 2 + r
    const distance = Math.abs(r - reading) * 2
    const fence = /^\s*```/.test(row.text)
    const color = fence || inFence
      ? theme.syntaxString
      : /^\s*#/.test(row.text)
        ? theme.syntaxKeyword
        : /^\s*([-*+]|\d+\.)\s/.test(row.text)
          ? theme.syntaxVariable
          : theme.terminalCommand
    if (fence) inFence = !inFence
    canvas.text(area.x, y, row.text, fade(color, bg, distance), bg, maxX)
  }
}

function searchBox(canvas: Canvas, theme: Theme, x: number, y: number, width: number, query: string, cursor: boolean, bg: number) {
  const edge = theme.editorLineNumber
  canvas.text(x, y, '╭' + '─'.repeat(width - 2) + '╮', edge, bg)
  canvas.set(x, y + 1, '│', edge, bg)
  canvas.set(x + width - 1, y + 1, '│', edge, bg)
  canvas.text(x, y + 2, '╰' + '─'.repeat(width - 2) + '╯', edge, bg)
  const room = width - 6
  const shown = query.length > room ? '…' + query.slice(query.length - room + 1) : query
  const end = canvas.text(canvas.text(x + 2, y + 1, '⌕ ', theme.editorLineNumber, bg), y + 1, shown, theme.fileTreeCurrentFileFg, bg)
  if (cursor) canvas.set(end, y + 1, ' ', theme.editorCursorCharFg, theme.editorCursorCharBg)
}

// The trash, in the explorer's lower right, once anything has gone to it: a
// can whose lid lifts as a file comes, and the file's name on its way there.
function paintTrash(canvas: Canvas, player: Player, theme: Theme, area: Box, offset: number) {
  const flight = player.flight
  if (!flight && player.trashed === 0) return
  const bg = theme.backgroundLeft
  const x = area.x + area.w - 7
  const y = area.y + area.h - 4
  if (x < area.x || y < area.y) return
  const isOpen = flight !== undefined && flight.t > 0.45
  const edge = theme.editorLineNumber
  canvas.text(x, y, isOpen ? ' ▁▁▁▁╱' : '      ', edge, bg)
  canvas.text(x, y + 1, isOpen ? '      ' : ' ▁▄▄▁ ', edge, bg)
  canvas.text(x, y + 2, '▕┊┊┊┊▏', edge, bg)
  canvas.text(x, y + 3, ' ▔▔▔▔ ', edge, bg)
  if (player.trashed > 0) canvas.text(x + 6, y + 3, String(player.trashed), theme.fileTreeDeleted, bg)
  if (!flight) return
  // From the file's row to the can's mouth, rising and then dropping in.
  const t = flight.t
  const eased = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2
  const fromX = area.x + flight.depth * 2 + 2
  const fromY = area.y + flight.row - offset
  const toX = x + 1
  const toY = y + 1
  const fx = Math.round(fromX + (toX - fromX) * eased)
  const fy = Math.round(fromY + (toY - fromY) * eased - Math.sin(Math.PI * t) * 3)
  const label = t > 0.85 ? '·' : flight.name.length > 20 ? flight.name.slice(0, 19) + '…' : flight.name
  canvas.text(Math.max(area.x, Math.min(fx, area.x + area.w - label.length)), Math.max(area.y, fy), label, theme.fileTreeDeleted, bg, area.x + area.w)
}

// The sidebar's search view, as the editor's: the query in its box, the
// count, then each file with its matching lines, the match itself marked.
function paintSearch(canvas: Canvas, player: Player, theme: Theme, area: Box) {
  const bg = theme.backgroundLeft
  const search = player.search!
  const maxX = area.x + area.w
  canvas.text(area.x, area.y, words.searchTitle, theme.editorLineNumber, bg)
  const box = theme.editorCursorLineBg
  canvas.background(area.x, area.y + 1, area.w, box)
  const room = area.w - 2
  const query = search.query.length > room ? '…' + search.query.slice(search.query.length - room + 1) : search.query
  const end = canvas.text(area.x + 1, area.y + 1, query, theme.fileTreeCurrentFileFg, box, maxX)
  if (player.active === 'explorer' && search.shown === 0) canvas.set(Math.min(end, maxX - 1), area.y + 1, ' ', theme.editorCursorCharFg, theme.editorCursorCharBg)
  const files = search.hits.slice(0, search.shown)
  const matches = files.reduce((n, hit) => n + Math.max(1, hit.matches.length), 0)
  if (search.shown > 0)
    canvas.text(area.x, area.y + 2, words.searchResults(search.total || matches, search.hits.length), theme.editorLineNumber, bg, maxX)
  let pattern: RegExp | undefined
  try {
    pattern = new RegExp(search.query, 'i')
  } catch {
    pattern = undefined
  }
  let y = area.y + 4
  for (const hit of files) {
    if (y >= area.y + area.h) break
    const name = hit.path.slice(hit.path.lastIndexOf('/') + 1)
    const folder = hit.path.slice(0, Math.max(0, hit.path.lastIndexOf('/')))
    let x = canvas.text(area.x, y, '▾ ' + name, theme.fileTreeDefault, bg, maxX)
    x = canvas.text(x + 1, y, folder, theme.editorLineNumber, bg, maxX - 4)
    if (hit.matches.length > 0) canvas.text(maxX - String(hit.matches.length).length - 1, y, String(hit.matches.length), theme.statusHash, bg, maxX)
    y++
    for (const match of hit.matches) {
      if (y >= area.y + area.h) break
      const text = match.text.trimStart()
      const found = pattern?.exec(text)
      const cut = Math.max(0, (found?.index ?? 0) - 8)
      const shown = (cut > 0 ? '…' : '') + text.slice(cut)
      const at = found ? found.index - cut + (cut > 0 ? 1 : 0) : -1
      canvas.text(area.x + 3, y, shown, theme.terminalOutput, bg, maxX)
      if (found && at >= 0)
        for (let i = 0; i < found[0].length && area.x + 3 + at + i < maxX; i++)
          canvas.set(area.x + 3 + at + i, y, shown[at + i] ?? ' ', theme.fileTreeCurrentFileFg, mix(MARKER, bg, 0.3))
      y++
    }
  }
}

// The quick-open palette, at the top middle of the pane: the pattern typed,
// and the files it finds beneath.
function paintPalette(canvas: Canvas, player: Player, theme: Theme, cursorOn: boolean) {
  const palette = player.palette!
  const width = Math.min(canvas.width - 4, 64)
  if (width < 16) return
  const x = Math.floor((canvas.width - width) / 2)
  const y = 1
  const fg = theme.fileTreeCurrentFileFg
  const bg = theme.editorCursorLineBg
  const rows = 1 + palette.shown
  canvas.fill(x, y, width, rows + 2, bg)
  canvas.text(x, y, '┌' + '─'.repeat(width - 2) + '┐', theme.separator, bg)
  for (let r = 1; r <= rows; r++) {
    canvas.set(x, y + r, '│', theme.separator, bg)
    canvas.set(x + width - 1, y + r, '│', theme.separator, bg)
  }
  canvas.text(x, y + rows + 1, '└' + '─'.repeat(width - 2) + '┘', theme.separator, bg)
  const end = canvas.text(x + 2, y + 1, palette.text, fg, bg, x + width - 2)
  if (cursorOn && palette.shown === 0) canvas.set(end, y + 1, ' ', theme.editorCursorCharFg, theme.editorCursorCharBg)
  palette.items.slice(0, palette.shown).forEach((item, i) => {
    const rowBg = i === 0 ? theme.fileTreeCurrentFileBg : bg
    canvas.background(x + 1, y + 2 + i, width - 2, rowBg)
    const name = item.slice(item.lastIndexOf('/') + 1)
    const nx = canvas.text(x + 2, y + 2 + i, name, fg, rowBg, x + width - 2)
    canvas.text(nx + 1, y + 2 + i, item.slice(0, Math.max(0, item.lastIndexOf('/'))), theme.editorLineNumber, rowBg, x + width - 2)
  })
}

type TreeRow = { dir: string } | { entry: FileEntry; name: string; indent: boolean }

function treeRows(files: Map<string, FileEntry>): TreeRow[] {
  const byDir = new Map<string, FileEntry[]>()
  for (const entry of files.values()) {
    const cut = entry.path.lastIndexOf('/')
    const dir = cut < 0 ? '' : entry.path.slice(0, cut)
    byDir.set(dir, [...(byDir.get(dir) ?? []), entry])
  }
  const rows: TreeRow[] = []
  for (const dir of [...byDir.keys()].sort()) {
    if (dir) rows.push({ dir })
    const entries = byDir.get(dir)!.map(entry => ({ entry, name: entry.path.slice(dir ? dir.length + 1 : 0) }))
    entries.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
    for (const { entry, name } of entries) rows.push({ entry, name, indent: dir !== '' })
  }
  return rows
}

function paintTree(canvas: Canvas, player: Player, theme: Theme, box: Box) {
  const bg = theme.backgroundLeft
  canvas.fill(box.x, box.y, box.w, box.h, bg)
  const area = inner(box)
  if (area.w <= 0 || area.h <= 0) return
  if (player.sidebar === 'search' && player.search) return paintSearch(canvas, player, theme, area)
  if (player.explorer.roots.length > 0) return paintExplorer(canvas, player, theme, area)
  const rows = treeRows(player.files)
  // Files the current turn has not touched recede.
  const turn = player.turn?.id
  const isOld = (entry: FileEntry) => turn !== undefined && entry.turn !== turn
  const oldDirs = new Set(
    [...new Set([...player.files.values()].map(entry => entry.path.slice(0, Math.max(0, entry.path.lastIndexOf('/')))))].filter(
      dir => [...player.files.values()].every(entry => !entry.path.startsWith(dir + '/') || isOld(entry)),
    ),
  )
  const selected = rows.findIndex(row => 'entry' in row && row.entry.path === player.currentPath)
  const offset =
    selected >= area.h ? Math.min(selected - Math.floor(area.h / 2), rows.length - area.h) : 0
  const maxX = area.x + area.w

  for (let r = 0; r < area.h && offset + r < rows.length; r++) {
    const index = offset + r
    const row = rows[index]
    const y = area.y + r
    const isSelected = index === selected
    const rowBg = isSelected ? theme.fileTreeCurrentFileBg : bg
    const isPast = 'dir' in row ? oldDirs.has(row.dir) : isOld(row.entry)
    const distance = Math.max(selected < 0 ? 0 : Math.abs(index - selected), isPast ? 14 : 0)
    const dim = (color: number) => fade(color, rowBg, distance)
    if (isSelected) canvas.background(area.x, y, area.w, rowBg)
    if ('dir' in row) {
      canvas.text(area.x, y, row.dir + '/', dim(theme.fileTreeDirectory), rowBg, maxX)
      continue
    }
    const { entry } = row
    const statusColor = entry.status === '+' ? theme.fileTreeAdded : theme.fileTreeModified
    let x = area.x + (row.indent ? 2 : 0)
    x = canvas.text(x, y, entry.status + ' ', dim(statusColor), rowBg, maxX)
    const nameColor = isSelected ? theme.fileTreeCurrentFileFg : theme.fileTreeDefault
    x = canvas.text(x, y, row.name, dim(nameColor), rowBg, maxX)
    x = canvas.text(x, y, ` +${entry.added}`, dim(theme.fileTreeStatsAdded), rowBg, maxX)
    canvas.text(x, y, ` -${entry.deleted}`, dim(theme.fileTreeStatsDeleted), rowBg, maxX)
  }
}

function elapsed(ms: number): string {
  const s = Math.floor(ms / 1000)
  return s < 60 ? `${s}s` : `${Math.floor(s / 60)}m ${s % 60}s`
}

// Claude's own mark, the one color the terminal keeps whatever the theme.
const CLAUDE = 0xd77757

// The shell as Claude meets it: what each command is for, the command, the
// head of what came back, the files written, and how the turn closed. Rows
// fade as they recede, the way older context does.
function paintTerminal(canvas: Canvas, player: Player, theme: Theme, box: Box, cursorOn: boolean) {
  const bg = theme.backgroundRight
  canvas.fill(box.x, box.y, box.w, box.h, bg)
  const area = inner(box)
  if (area.w <= 0 || area.h <= 0) return
  const lines = player.terminal
  const start = Math.max(0, lines.length - area.h)
  const maxX = area.x + area.w
  const fit = (text: string, room: number, keepTail = false) =>
    text.length <= room ? text : room <= 1 ? '' : keepTail ? '…' + text.slice(text.length - room + 1) : text.slice(0, room - 1) + '…'

  for (let i = start; i < lines.length; i++) {
    const line = lines[i]
    const y = area.y + i - start
    const isLast = i === lines.length - 1
    const age = Math.min(20, (lines.length - 1 - i) * 3)
    const ink = (color: number) => fade(color, bg, age)
    let x = area.x
    const put = (text: string, color: number) => (x = canvas.text(x, y, text, ink(color), bg, maxX))
    const right = line.right ?? ''
    const room = (lead: number) => Math.max(0, area.w - lead - (right ? right.length + 2 : 0))

    switch (line.kind) {
      case 'rule': {
        const [id = '', time = ''] = line.text.split(' · ')
        put('── ', theme.separator)
        put(id, theme.statusHash)
        put(' · ', theme.separator)
        put(time, theme.statusDate)
        put(' ' + '─'.repeat(Math.max(0, maxX - x - 1)), theme.separator)
        break
      }
      case 'intent':
        put('# ' + fit(line.text, area.w - 2), theme.syntaxComment)
        break
      case 'command': {
        put('❯ ', CLAUDE)
        const isTyping = line.right === undefined
        put(fit(line.text, room(2) - (isTyping ? 1 : 0), isTyping), theme.terminalCommand)
        if (isLast && isTyping && cursorOn && player.active === 'terminal')
          canvas.set(Math.min(x, maxX - 1), y, ' ', theme.terminalCursorFg, theme.terminalCursorBg)
        if (right) {
          const cut = right.indexOf(' ')
          x = maxX - right.length
          put(right.slice(0, cut + 1), theme.terminalOutput)
          put(right.slice(cut + 1), line.ok ? theme.fileTreeAdded : theme.fileTreeDeleted)
        } else if (line.running && line.startedAt) {
          // Still running: a spinner and the time so far.
          const spinner = '⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏'
          const now = Date.now()
          const status = `${spinner[Math.floor(now / 100) % spinner.length]} ${elapsed(now - line.startedAt)}`
          x = maxX - status.length
          put(status, theme.editorCursorCharBg)
        }
        break
      }
      case 'commit': {
        put('◆ ', CLAUDE)
        put(line.sha ?? '', theme.statusHash)
        if (line.branch) put(` (${line.branch})`, theme.statusDate)
        put(' ' + fit(line.text, Math.max(0, maxX - x - 1)), theme.terminalCommand)
        break
      }
      case 'cast':
        put('▶ ', theme.fileTreeDeleted)
        put(fit(line.text, Math.max(0, maxX - x - (right ? right.length + 2 : 0))), theme.terminalCommand)
        if (right) {
          x = maxX - right.length
          put(right, theme.editorLineNumber)
        }
        break
      case 'trash':
        put('✗ ', theme.fileTreeDeleted)
        put(words.movedToTrash + '  ', theme.terminalOutput)
        put(fit(line.text, Math.max(0, maxX - x)), theme.fileTreeDeleted)
        break
      case 'output':
        put(line.first ? '  ⎿  ' : '     ', theme.separator)
        put(fit(line.text, area.w - 5), theme.terminalOutput)
        break
      case 'more':
        put('     ' + fit(line.text, area.w - 5), theme.separator)
        break
      case 'edit': {
        put('✎ ', theme.fileTreeModified)
        put(fit(line.text, room(2)), theme.terminalCommand)
        if (right) {
          const [added = '', deleted = ''] = right.split(' ')
          x = maxX - right.length
          put(added + ' ', theme.fileTreeStatsAdded)
          put(deleted, theme.fileTreeStatsDeleted)
        }
        break
      }
      case 'done':
        put('✻ ', CLAUDE)
        put(fit(line.text, area.w - 2), theme.terminalOutput)
        break
      case 'fail':
        put('✗ ' + fit(line.text, area.w - 2), theme.fileTreeDeleted)
        break
      case 'progress': {
        const done = (line.fraction ?? 0) >= 1
        put(done ? '✓ ' : line.up ? '↑ ' : '↓ ', done ? theme.fileTreeAdded : CLAUDE)
        put(fit(line.text, Math.max(8, Math.floor(area.w / 3))) + ' ', theme.terminalCommand)
        const barWidth = Math.max(4, maxX - x - right.length - 2)
        const full = Math.round(barWidth * (line.fraction ?? 0))
        put('━'.repeat(full), done ? theme.fileTreeAdded : theme.editorCursorCharBg)
        put('─'.repeat(barWidth - full), theme.separator)
        x = maxX - right.length
        put(right, theme.terminalOutput)
        break
      }
      case 'prompt':
        put('❯ ', CLAUDE)
        if (isLast && cursorOn) canvas.set(x, y, ' ', theme.terminalCursorFg, theme.terminalCursorBg)
        break
    }
  }
}

function paintDialog(canvas: Canvas, dialog: { title: string; text: string }, theme: Theme) {
  const width = Math.min(canvas.width, Math.max(60, dialog.text.length + 10))
  if (width < 8 || canvas.height < 3) return
  const x = Math.floor((canvas.width - width) / 2)
  const y = Math.floor((canvas.height - 3) / 2)
  const fg = theme.fileTreeCurrentFileFg
  const bg = theme.editorCursorLineBg
  canvas.fill(x, y, width, 3, bg)
  canvas.text(x, y, '┌' + '─'.repeat(width - 2) + '┐', fg, bg)
  canvas.text(x + 1, y, dialog.title.slice(0, width - 2), fg, bg)
  canvas.set(x, y + 1, '│', fg, bg)
  canvas.set(x + width - 1, y + 1, '│', fg, bg)
  canvas.text(x, y + 2, '└' + '─'.repeat(width - 2) + '┘', fg, bg)
  const room = width - 4
  const shown = dialog.text.length > room ? '…' + dialog.text.slice(dialog.text.length - room + 1) : dialog.text
  canvas.text(x + 2, y + 1, shown, fg, bg)
}

files.hooks/player.ts:
// The playback engine: Claude's work arrives as events (a turn begins, a file
// changes, a command runs, the turn ends), each becomes a script of small steps
// the way gitlogue scripts a commit, and `advance` plays the script against the
// clock. Pacing constants are gitlogue's, as multiples of the typing speed.

import type {
  GitlogueBrowser,
  GitlogueEvent,
  GitlogueFlight,
  GitlogueImage,
  GitloguePalette,
  GitlogueSearch,
  GitlogueFileEntry,
  GitloguePlace,
  GitlogueSaved,
  GitlogueTermLine,
  GitlogueTurn,
  GitlogueView,
} from '../types'
import { countChanges, diffLines, type Hunk } from './diff'
import { chainTo, Explorer, nameOf, parentOf, type DirEntry } from './explorer'
import { cellText } from './cells'
import { words } from './i18n'
import { Highlighter } from './highlight'

const CURSOR_MOVE_PAUSE = 0.5
const CURSOR_MOVE_SHORT_MULTIPLIER = 1.0
const CURSOR_MOVE_MEDIUM_MULTIPLIER = 0.3
const CURSOR_MOVE_LONG_MULTIPLIER = 0.05
const MAX_SCROLL_STEPS = 60
const MIN_LOG_STEPS = 50
const LOG_SCALE_FACTOR = 8.0
const DELETE_LINE_PAUSE = 10.0
const INSERT_LINE_PAUSE = 6.7
const HUNK_PAUSE = 50.0
const CHECKOUT_PAUSE = 16.7
const CHECKOUT_OUTPUT_PAUSE = 33.3
const OPEN_FILE_FIRST_PAUSE = 33.3
const OPEN_FILE_PAUSE = 50.0
const OPEN_CMD_PAUSE = 16.7
const FILE_SWITCH_PAUSE = 26.7
const GIT_ADD_PAUSE = 33.3
const GIT_ADD_CMD_PAUSE = 16.7
const PUSH_OUTPUT_PAUSE = 10.0

const MAX_TERMINAL_LINES = 300
const EXPAND_PAUSE = 6.0
const SELECT_STEP_PAUSE = 1.5
const PAGE_LOAD_STEPS = 18
const MAX_READ_SWEEP = 120
const FLY_STEPS = 16
const DOWNLOAD_STEPS = 28

type Screen = 'code' | 'browser' | 'image' | 'cast'

// A recording of one of Claude's own screens, as it plays.
export type Cast = { screen: string; width: number; height: number; speed: number; seconds: number }

const EMPTY_BROWSER: GitlogueBrowser = {
  url: '',
  page: 'home',
  query: '',
  results: [],
  shown: 0,
  selected: -1,
  stats: '',
  body: [],
  scroll: 0,
  loading: 1,
}
// Past these a change is a machine's output, not something typed: it is
// counted in the tree and noted in the terminal, never replayed key by key.
const MAX_TYPED_LINE = 1000
const MAX_TYPED_CHARS = 100_000
const LOCK_FILES = new Set([
  'package-lock.json', 'yarn.lock', 'pnpm-lock.yaml', 'bun.lockb', 'Cargo.lock', 'poetry.lock', 'uv.lock',
  'Pipfile.lock', 'Gemfile.lock', 'composer.lock', 'go.sum', 'flake.lock', 'mix.lock', 'pubspec.lock',
])

export type TurnInfo = GitlogueTurn
export type FileEntry = GitlogueFileEntry
export type PlayerEvent = GitlogueEvent
export type TermLine = GitlogueTermLine

type FileChange = { path: string; oldLines: string[]; entry: FileEntry }

type StepBody =
  | { k: 'char'; line: number; col: number; ch: string }
  | { k: 'backspace'; line: number; col: number }
  | { k: 'insertLine'; line: number; text: string }
  | { k: 'deleteLine'; line: number }
  | { k: 'move'; line: number; col: number }
  | { k: 'pause' }
  | { k: 'switchFile'; change: FileChange }
  | { k: 'count'; entry: FileEntry }
  | { k: 'root'; root: string }
  | { k: 'list'; dir: string; entries: DirEntry[]; ensure?: DirEntry }
  | { k: 'expand'; dir: string }
  | { k: 'select'; path: string }
  | { k: 'screen'; screen: Screen }
  | { k: 'browse'; set: Partial<GitlogueBrowser> }
  | { k: 'boxChar'; ch: string }
  | { k: 'addressChar'; ch: string }
  | { k: 'image'; image: GitlogueImage }
  | { k: 'progress'; fraction: number; right?: string }
  | { k: 'mark'; from: number; line: number; col: number }
  | { k: 'sidebar'; sidebar: 'explorer' | 'search' }
  | { k: 'search'; set: Partial<GitlogueSearch> }
  | { k: 'searchChar'; ch: string }
  | { k: 'palette'; set: Partial<GitloguePalette> | null }
  | { k: 'paletteChar'; ch: string }
  | { k: 'termRunning' }
  | { k: 'commitMark'; root: string }
  | { k: 'flyStart'; file: string }
  | { k: 'fly'; t: number }
  | { k: 'trash'; file: string }
  | { k: 'castStart'; cast: Cast }
  | { k: 'castFrame'; file: string }
  | { k: 'castEnd'; remove: string[] }
  | { k: 'dialogOpen' }
  | { k: 'dialogChar'; ch: string }
  | { k: 'termLine'; line: TermLine }
  | { k: 'termChar'; ch: string }
  | { k: 'termResult'; right: string; ok: boolean }
  | { k: 'termDone'; durationMs: number; aborted: boolean }
  | { k: 'resetTurn'; turn: TurnInfo }

type Step = StepBody & { dur: number }

const splitLines = (text: string) => (text === '' ? [] : text.replace(/\r?\n$/, '').split(/\r?\n/).map(cellText))
const indentOf = (line: string | undefined) => (line ?? '').length - (line ?? '').trimStart().length

export class Player {
  // What the panes draw.
  lines: string[] = ['']
  cursorLine = 0
  cursorCol = 0
  active: 'editor' | 'terminal' | 'explorer' = 'terminal'
  hasFile = false
  terminal: TermLine[] = []
  // The word Claude Code closed a turn of this length with (`Cogitated`), when known.
  wordFor: (durationMs: number) => string | undefined = () => undefined
  dialog: { title: string; text: string } | undefined
  turn: TurnInfo | undefined
  files = new Map<string, FileEntry>()
  currentPath: string | undefined
  readonly highlighter = new Highlighter()
  // Bumped whenever the turn shown changes, for the drawing that shows it.
  turnVersion = 0

  // The explorer the panes draw, and the copy the script walks ahead on.
  explorer = new Explorer()
  // What the editor's area shows: code, a browser, or a picture.
  screen: Screen = 'code'
  browser: GitlogueBrowser = { ...EMPTY_BROWSER }
  image: GitlogueImage | undefined
  // Lines read with the highlighter, the sidebar's view, the quick-open
  // palette, a file on its way to the trash, and how many went there.
  marks: { from: number; line: number; col: number } | undefined
  sidebar: 'explorer' | 'search' = 'explorer'
  search: GitlogueSearch | undefined
  palette: GitloguePalette | undefined
  flight: GitlogueFlight | undefined
  trashed = 0
  // A screen recording playing in the editor's area, its current frame, and
  // the files played through, for the pane to delete.
  cast: Cast | undefined
  castFrame: string | undefined
  removals: string[] = []
  private planSidebar: 'explorer' | 'search' = 'explorer'
  // Bumped when the screen or its picture changes, for the drawing that holds it.
  sceneVersion = 0
  private planScreen: Screen = 'code'
  private planBrowser: GitlogueBrowser = { ...EMPTY_BROWSER }
  private plan = new Explorer()
  private planKeep = new Set<string>()
  // A file that starts empty shows one blank line, which its first typed line takes over.
  private isBlank = false
  private steps: Step[] = []
  private next = 0
  // Absolute index of steps[0], so event boundaries survive compaction.
  private base = 0
  // Events not yet fully played, each with the absolute step index it ends at,
  // and the panes as they stood when the oldest of them began.
  private segments: { event: PlayerEvent; end: number }[] = []
  private checkpoint: GitlogueView = this.view()
  // Bumped whenever what `save` returns changes.
  saveVersion = 0
  private wait = 0
  private remaining = 0
  private filesThisTurn = 0
  // The file the script last left in the editor, and its text then.
  private scriptedPath: string | undefined
  private scriptedText: string | undefined

  private readonly speedMs: number
  private readonly maxLagMs: number

  constructor(speedMs: number, maxLagMs: number) {
    this.speedMs = speedMs
    this.maxLagMs = maxLagMs
  }

  // A command still running at the bottom of the terminal.
  get hasRunning(): boolean {
    return this.terminal.some(line => line.kind === 'command' && line.running === true)
  }

  get isIdle(): boolean {
    return this.next >= this.steps.length
  }

  enqueue(event: PlayerEvent) {
    this.script(event)
    this.segments.push({ event, end: this.base + this.steps.length })
    this.saveVersion++
    this.settle()
  }

  // The replay as it stands: the panes at the oldest unfinished event, and the
  // events from there on, to pick up after a reload.
  save(): GitlogueSaved {
    // A recording's frames do not outlive this load: it is not kept to replay.
    return { view: this.checkpoint, pending: this.segments.map(segment => segment.event).filter(event => event.type !== 'cast') }
  }

  restore(saved: GitlogueSaved) {
    const view = saved.view
    this.lines = view.lines.length > 0 ? view.lines.slice() : ['']
    this.cursorLine = view.cursorLine
    this.cursorCol = view.cursorCol
    this.active = view.active
    this.hasFile = view.hasFile
    this.isBlank = view.isBlank
    // Records from before the terminal had structure hold plain strings.
    this.terminal = view.terminal.map(line =>
      typeof line === 'string' ? { kind: 'output' as const, text: line } : { ...line },
    )
    this.turn = view.turn ?? undefined
    this.files = new Map(view.files.map(entry => [entry.path, { ...entry }]))
    this.currentPath = view.currentPath ?? undefined
    this.explorer = Explorer.from(view.explorer)
    this.screen = view.screen === 'cast' ? 'code' : (view.screen ?? 'code')
    this.browser = view.browser ? { ...view.browser, results: view.browser.results.slice(), body: view.browser.body.slice() } : { ...EMPTY_BROWSER }
    this.image = view.image ? { ...view.image } : undefined
    this.marks = view.marks ? { ...view.marks } : undefined
    this.sidebar = view.sidebar ?? 'explorer'
    this.planSidebar = this.sidebar
    this.search = view.search ? { ...view.search, hits: view.search.hits.slice() } : undefined
    this.palette = undefined
    this.flight = undefined
    this.trashed = view.trashed ?? 0
    this.planScreen = this.screen
    this.planBrowser = { ...this.browser }
    this.sceneVersion++
    this.plan = this.explorer.clone()
    this.planKeep = new Set(view.files.flatMap(entry => (entry.file ? [entry.file] : [])))
    this.dialog = undefined
    if (view.hasFile && view.currentPath) this.highlighter.setPath(view.currentPath)
    this.turnVersion++
    this.steps = []
    this.next = 0
    this.base = 0
    this.wait = 0
    this.remaining = 0
    this.segments = []
    this.filesThisTurn = view.files.length
    this.scriptedPath = view.hasFile ? (view.currentPath ?? undefined) : undefined
    this.scriptedText = view.lines.join('\n')
    this.checkpoint = this.view()
    this.saveVersion++
    for (const event of saved.pending) this.enqueue(event)
  }

  private setScreen(screen: Screen) {
    if (this.screen === screen) return
    this.screen = screen
    this.sceneVersion++
  }

  // A new row, taking the place of an idle prompt left at the bottom.
  private addLine(line: TermLine) {
    if (this.terminal[this.terminal.length - 1]?.kind === 'prompt') this.terminal.pop()
    this.terminal.push(line)
  }

  // Back to an empty pane, as a session with nothing replayed yet.
  reset() {
    this.restore({
      view: {
        lines: [''],
        cursorLine: 0,
        cursorCol: 0,
        active: 'terminal',
        hasFile: false,
        isBlank: false,
        terminal: [],
        turn: null,
        files: [],
        currentPath: null,
      },
      pending: [],
    })
  }

  view(): GitlogueView {
    return {
      lines: this.lines.slice(),
      cursorLine: this.cursorLine,
      cursorCol: this.cursorCol,
      active: this.active,
      hasFile: this.hasFile,
      isBlank: this.isBlank,
      terminal: this.terminal.map(line => ({ ...line })),
      turn: this.turn ?? null,
      files: [...this.files.values()].map(entry => ({ ...entry })),
      currentPath: this.currentPath ?? null,
      explorer: this.explorer.save(),
      screen: this.screen,
      browser: { ...this.browser, results: this.browser.results.slice(), body: this.browser.body.slice() },
      image: this.image ? { ...this.image } : undefined,
      marks: this.marks ? { ...this.marks } : undefined,
      sidebar: this.sidebar,
      search: this.search ? { ...this.search, hits: this.search.hits.slice() } : undefined,
      trashed: this.trashed,
    }
  }

  // Retires the events whose steps have all run.
  private settle() {
    let moved = false
    while (this.segments.length > 0 && this.segments[0].end <= this.base + this.next) {
      this.segments.shift()
      moved = true
    }
    if (moved) {
      this.checkpoint = this.view()
      this.saveVersion++
    }
  }

  private script(event: PlayerEvent) {
    const before = this.steps.length
    switch (event.type) {
      case 'turn':
        this.scriptTurn(event.turn)
        break
      case 'edit':
        this.scriptEdit(event)
        break
      case 'command':
        // The intent arrives whole, as a thought does; the command is typed.
        if (event.description?.trim()) {
          this.push({ k: 'termLine', line: { kind: 'intent', text: event.description.trim() } })
          this.pause(OPEN_CMD_PAUSE)
        }
        this.push({ k: 'termLine', line: { kind: 'command', text: '', startedAt: event.startedAt } })
        for (const ch of cellText(event.command.replace(/\s*\n\s*/g, ' ; ')).slice(0, 240)) this.push({ k: 'termChar', ch }, this.typing())
        this.push({ k: 'termRunning' }, 0)
        this.pause(GIT_ADD_CMD_PAUSE)
        break
      case 'output': {
        const status = event.failed ? (event.exitCode ? `✗ ${event.exitCode}` : '✗') : '✓'
        this.push({ k: 'termResult', right: `${formatDuration(event.durationMs, true)} ${status}`, ok: !event.failed })
        event.lines.forEach((text, i) => this.push({ k: 'termLine', line: { kind: 'output', text, first: i === 0 } }, this.speedMs / 2))
        if (event.total > event.lines.length)
          this.push({ k: 'termLine', line: { kind: 'more', text: words.moreLines(event.total - event.lines.length) } })
        this.pause(PUSH_OUTPUT_PAUSE)
        break
      }
      case 'search':
        this.scriptSearch(event)
        break
      case 'fetch':
        this.scriptFetch(event)
        break
      case 'image':
        this.scriptImage(event)
        break
      case 'download':
        this.scriptDownload(event)
        break
      case 'read':
        this.scriptRead(event)
        break
      case 'codesearch':
        this.scriptCodeSearch(event)
        break
      case 'findfiles':
        this.scriptFindFiles(event)
        break
      case 'git':
        this.scriptGit(event)
        break
      case 'delete':
        this.scriptDelete(event)
        break
      case 'cast':
        this.scriptCast(event)
        break
      case 'done':
        this.pause(PUSH_OUTPUT_PAUSE)
        this.push({ k: 'termDone', durationMs: event.durationMs, aborted: event.aborted })
        break
    }
    for (let i = before; i < this.steps.length; i++) this.remaining += this.steps[i].dur
  }

  // Plays the script for `dtMs` of wall time, sped up so that what is queued
  // never takes longer than the lag allowed. Returns whether anything changed.
  advance(dtMs: number): boolean {
    if (this.isIdle) return false
    const speedup = Math.max(1, this.remaining / this.maxLagMs)
    let budget = dtMs * speedup
    let changed = false
    let executed = 0
    while (this.next < this.steps.length && executed < 50000) {
      if (this.wait > budget) {
        this.wait -= budget
        break
      }
      budget -= this.wait
      const step = this.steps[this.next++]
      this.execute(step)
      this.wait = step.dur
      this.remaining = Math.max(0, this.remaining - step.dur)
      changed = true
      executed++
      if (this.segments.length > 0 && this.segments[0].end <= this.base + this.next) this.settle()
    }
    if (this.isIdle) {
      this.base += this.steps.length
      this.steps = []
      this.next = 0
      this.wait = 0
      this.remaining = 0
    } else if (this.next > 4096) {
      this.base += this.next
      this.steps = this.steps.slice(this.next)
      this.next = 0
    }
    return changed
  }

  // Applies everything queued at once: for while nobody is watching.
  flush(): boolean {
    if (this.isIdle) return false
    while (!this.isIdle) this.advance(Number.MAX_SAFE_INTEGER)
    return true
  }

  private push(step: StepBody, dur = this.speedMs) {
    this.steps.push({ ...step, dur })
  }

  private pause(multiplier: number) {
    this.push({ k: 'pause' }, this.speedMs * multiplier)
  }

  private typing(factor = 1) {
    return this.speedMs * factor * (0.7 + Math.random() * 0.6)
  }

  private scriptTurn(turn: TurnInfo) {
    this.filesThisTurn = 0
    this.push({ k: 'termLine', line: { kind: 'rule', text: `${turn.id} · ${turn.date.slice(-8)}` } })
    this.pause(CHECKOUT_OUTPUT_PAUSE)
    this.push({ k: 'resetTurn', turn })
  }

  private scriptEdit(event: Extract<PlayerEvent, { type: 'edit' }>) {
    const oldLines = splitLines(event.before)
    const newLines = splitLines(event.after)
    const hunks = diffLines(oldLines, newLines)
    if (hunks.length === 0) return
    const { added, deleted } = countChanges(hunks)
    const skipped = untypeable(event.path, hunks)
    if (skipped) {
      this.pause(CHECKOUT_PAUSE)
      this.push({ k: 'count', entry: { path: event.path, status: event.created ? '+' : '~', added, deleted, file: event.file } })
      this.push({
        k: 'termLine',
        line: { kind: 'edit', text: `${cellText(event.path)} · ${words.notReplayed(skipped)}`, right: `+${added} −${deleted}`, ok: true },
      })
      this.pause(GIT_ADD_CMD_PAUSE)
      return
    }
    const change: FileChange = {
      path: event.path,
      oldLines,
      entry: { path: event.path, status: event.created ? '+' : '~', added, deleted, file: event.file },
    }

    // The file already open, as the last change left it: keep typing in place.
    const isOpen = this.scriptedPath === event.path
    // Back from a browser or a picture, the file is opened again even if it was the last.
    const wasCode = this.planScreen === 'code'
    this.planScreen = 'code'
    if (isOpen && wasCode && this.scriptedText === oldLines.join('\n')) {
      this.pause(CHECKOUT_PAUSE)
    } else if (isOpen) {
      this.pause(OPEN_CMD_PAUSE)
      this.push({ k: 'switchFile', change })
      this.pause(FILE_SWITCH_PAUSE)
    } else if (event.file && event.place) {
      this.pause(this.filesThisTurn++ === 0 ? OPEN_FILE_FIRST_PAUSE : OPEN_FILE_PAUSE)
      this.scriptNavigate(event.file, event.place)
      this.push({ k: 'switchFile', change })
      this.pause(FILE_SWITCH_PAUSE)
    } else {
      this.pause(this.filesThisTurn++ === 0 ? OPEN_FILE_FIRST_PAUSE : OPEN_FILE_PAUSE)
      this.push({ k: 'dialogOpen' })
      this.pause(5.0)
      for (const ch of cellText(event.path)) this.push({ k: 'dialogChar', ch }, this.typing(2))
      this.pause(OPEN_CMD_PAUSE)
      this.push({ k: 'switchFile', change })
      this.pause(FILE_SWITCH_PAUSE)
    }
    this.push({ k: 'count', entry: change.entry })
    this.scriptedPath = event.path
    this.scriptedText = newLines.join('\n')
    this.scriptHunks(oldLines, hunks)
    this.pause(GIT_ADD_PAUSE)
    this.push({ k: 'termLine', line: { kind: 'edit', text: cellText(event.path), right: `+${added} −${deleted}`, ok: true } })
    this.pause(GIT_ADD_CMD_PAUSE)
  }

  // Walks the explorer to `file` as a person would: down from where the
  // selection is, opening each closed folder on the way, then onto the file.
  private scriptNavigate(file: string, place: GitloguePlace) {
    const plan = this.plan
    if (this.planSidebar !== 'explorer') {
      this.push({ k: 'sidebar', sidebar: 'explorer' }, 0)
      this.planSidebar = 'explorer'
      this.pause(OPEN_CMD_PAUSE)
    }
    if (!plan.roots.includes(place.root)) {
      this.push({ k: 'root', root: place.root })
      plan.addRoot(place.root)
    }
    const chain = chainTo(place.root, file)
    chain.forEach((dir, i) => {
      const entries = place.listings[dir]
      if (!entries) return
      const ensure = { name: nameOf(chain[i + 1] ?? file), dir: i + 1 < chain.length }
      this.push({ k: 'list', dir, entries, ensure }, 0)
      plan.list(dir, entries, ensure)
    })
    this.planKeep.add(file)
    for (const dir of chain) {
      if (plan.expanded.has(dir)) continue
      this.scriptSelect(dir)
      this.pause(EXPAND_PAUSE)
      this.push({ k: 'expand', dir })
      plan.expanded.add(dir)
      this.pause(EXPAND_PAUSE * 1.5)
    }
    this.scriptSelect(file)
    this.pause(OPEN_CMD_PAUSE)
  }

  // The selection stepping row by row to `target`, easing in and out.
  private scriptSelect(target: string) {
    const plan = this.plan
    const rows = plan.rows(this.planKeep)
    const to = rows.findIndex(row => row.path === target)
    const from = Math.max(0, rows.findIndex(row => row.path === plan.selected))
    if (to >= 0 && to !== from) {
      const distance = Math.abs(to - from)
      const count = Math.min(distance, MAX_SCROLL_STEPS)
      let last = from
      for (let i = 1; i <= count; i++) {
        const t = i / count
        const eased = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2
        const index = Math.round(from + (to - from) * eased)
        if (index === last) continue
        last = index
        this.push({ k: 'select', path: rows[index].path }, 0)
        this.pause(SELECT_STEP_PAUSE)
      }
    }
    if (plan.selected !== target) this.push({ k: 'select', path: target }, 0)
    plan.selected = target
  }

  private toScreen(screen: Screen) {
    if (this.planScreen === screen) return
    this.push({ k: 'screen', screen }, 0)
    this.planScreen = screen
    this.pause(FILE_SWITCH_PAUSE)
  }

  private browse(set: Partial<GitlogueBrowser>, dur = this.speedMs) {
    this.push({ k: 'browse', set }, dur)
    this.planBrowser = { ...this.planBrowser, ...set }
  }

  // A page coming in: the bar across the top fills, unevenly, as pages do.
  private scriptLoad() {
    let loaded = 0
    for (let i = 1; i <= PAGE_LOAD_STEPS; i++) {
      loaded = Math.min(1, loaded + (Math.random() * 2) / PAGE_LOAD_STEPS)
      this.browse({ loading: i === PAGE_LOAD_STEPS ? 1 : loaded }, this.speedMs * (1 + Math.random() * 2))
    }
  }

  // A search, the way a person runs one: the search page, the query typed into
  // its box, Enter, the results page loading, then the results read down.
  private scriptSearch(event: Extract<PlayerEvent, { type: 'search' }>) {
    this.toScreen('browser')
    this.browse({ url: 'google.com', page: 'home', query: '', results: [], shown: 0, selected: -1, body: [], scroll: 0, loading: 1 })
    this.pause(CHECKOUT_OUTPUT_PAUSE)
    for (const ch of cellText(event.query).slice(0, 200)) this.push({ k: 'boxChar', ch }, this.typing())
    this.pause(OPEN_CMD_PAUSE)
    const results = event.results.slice(0, 10).map(link => ({ title: cellText(link.title), url: cellText(link.url) }))
    const seconds = (event.durationMs / 1000).toFixed(2)
    this.browse({
      url: `google.com/search?q=${encodeURIComponent(event.query).replace(/%20/g, '+')}`,
      page: 'results',
      results,
      shown: 0,
      stats: words.webStats(results.length, seconds),
      loading: 0,
    })
    this.scriptLoad()
    for (let i = 1; i <= results.length; i++) this.browse({ shown: i }, this.speedMs * 3)
    this.pause(HUNK_PAUSE)
  }

  // A page opened: clicked from the results when it is one of them, else its
  // address typed; then loaded and read down a screenful at a time.
  private scriptFetch(event: Extract<PlayerEvent, { type: 'fetch' }>) {
    this.toScreen('browser')
    const plan = this.planBrowser
    const target = plan.page === 'results' ? plan.results.findIndex(link => sameAddress(link.url, event.url)) : -1
    if (target >= 0) {
      const from = Math.max(0, plan.selected)
      const step = target >= from ? 1 : -1
      for (let i = from; i !== target + step; i += step) this.browse({ selected: i }, this.speedMs * 4)
      this.pause(OPEN_CMD_PAUSE)
    } else {
      this.browse({ url: '' }, this.speedMs * 4)
      for (const ch of cellText(event.url.replace(/^https?:\/\//, '')).slice(0, 160)) this.push({ k: 'addressChar', ch }, this.typing(0.6))
      this.pause(OPEN_CMD_PAUSE)
    }
    const body = event.text.split('\n').map(cellText)
    this.browse({ url: cellText(event.url.replace(/^https?:\/\//, '')), page: 'page', body, scroll: 0, loading: 0, selected: -1 })
    this.scriptLoad()
    this.pause(CHECKOUT_OUTPUT_PAUSE)
    const reading = Math.min(body.length, 60)
    for (let line = 1; line <= reading; line++) this.browse({ scroll: line }, this.speedMs * (line % 8 === 0 ? 12 : 3))
    this.pause(HUNK_PAUSE)
  }

  // A picture looked at: found in the explorer, opened, and held a moment.
  private scriptImage(event: Extract<PlayerEvent, { type: 'image' }>) {
    if (event.place) this.scriptNavigate(event.file, event.place)
    this.push({ k: 'image', image: { path: cellText(event.path), png: event.png, width: event.width, height: event.height } }, 0)
    this.planScreen = 'image'
    this.pause(HUNK_PAUSE * 1.5)
  }

  // A download: a bar under its command fills at an uneven pace over about
  // the time it took, then the file lands in its folder.
  private scriptDownload(event: Extract<PlayerEvent, { type: 'download' }>) {
    const name = cellText(event.path.slice(event.path.lastIndexOf('/') + 1))
    const total = formatBytes(event.bytes)
    this.push({ k: 'termLine', line: { kind: 'progress', text: name, fraction: 0, right: `0 B / ${total}` } })
    const span = Math.min(6000, Math.max(900, event.durationMs))
    let fraction = 0
    for (let i = 1; i <= DOWNLOAD_STEPS; i++) {
      fraction = i === DOWNLOAD_STEPS ? 1 : Math.min(0.97, fraction + (Math.random() * 2) / DOWNLOAD_STEPS)
      const right = `${formatBytes(event.bytes * fraction)} / ${total}`
      this.push({ k: 'progress', fraction, right }, (span / DOWNLOAD_STEPS) * (0.4 + Math.random() * 1.2))
    }
    this.push({ k: 'progress', fraction: 1, right: `${total} · ${formatDuration(event.durationMs, true)}` })
    if (event.place) {
      const folder = event.file.slice(0, event.file.lastIndexOf('/'))
      const entries = event.place.listings[folder]
      if (entries) {
        if (!this.plan.roots.includes(event.place.root)) {
          this.push({ k: 'root', root: event.place.root })
          this.plan.addRoot(event.place.root)
        }
        const ensure = { name: nameOf(event.file), dir: false }
        this.push({ k: 'list', dir: folder, entries, ensure }, 0)
        this.plan.list(folder, entries, ensure)
      }
      this.planKeep.add(event.file)
    }
    this.push({ k: 'count', entry: { path: event.path, status: '+', added: 0, deleted: 0, file: event.file, note: total } })
    this.pause(GIT_ADD_CMD_PAUSE)
  }

  // Code read with a highlighter: the file opened if it is not already, the
  // cursor brought to what was read, and the pen drawn along each line of it.
  private scriptRead(event: Extract<PlayerEvent, { type: 'read' }>) {
    const lines = splitLines(event.text)
    if (lines.length === 0 || isLog(event.path)) return
    const isOpen = this.planScreen === 'code' && this.scriptedPath === event.path && this.scriptedText === lines.join('\n')
    this.planScreen = 'code'
    if (!isOpen) {
      this.pause(this.filesThisTurn === 0 ? OPEN_FILE_FIRST_PAUSE : OPEN_FILE_PAUSE)
      if (event.place) this.scriptNavigate(event.file, event.place)
      const entry: FileEntry = { path: event.path, status: '~', added: 0, deleted: 0, file: event.file }
      this.push({ k: 'switchFile', change: { path: event.path, oldLines: lines, entry } })
      this.pause(FILE_SWITCH_PAUSE)
      this.scriptedPath = event.path
      this.scriptedText = lines.join('\n')
    }
    const from = Math.min(lines.length - 1, Math.max(0, event.startLine - 1))
    const to = Math.min(lines.length, from + Math.max(1, event.numLines))
    this.scriptCursorMove(0, from, lines)
    this.pause(OPEN_CMD_PAUSE)
    const swept = Math.min(to - from, MAX_READ_SWEEP)
    for (let line = from; line < from + swept; line++) {
      const length = lines[line].length
      for (const share of [0.34, 0.67, 1])
        this.push({ k: 'mark', from, line, col: Math.round(length * share) }, this.speedMs * (length > 0 ? 1.4 : 0.3))
      if ((line - from) % 6 === 5) this.pause(4)
    }
    if (to - from > swept) this.push({ k: 'mark', from, line: to - 1, col: lines[to - 1].length })
    this.pause(HUNK_PAUSE)
  }

  // A search through code, as the editor's search view runs one: the query
  // typed into its box, then the matching files listed one by one, each with
  // its lines.
  private scriptCodeSearch(event: Extract<PlayerEvent, { type: 'codesearch' }>) {
    this.push({ k: 'sidebar', sidebar: 'search' }, 0)
    this.planSidebar = 'search'
    this.push({ k: 'search', set: { query: '', hits: [], shown: 0, total: event.total } })
    this.pause(OPEN_CMD_PAUSE)
    for (const ch of cellText(event.query).slice(0, 80)) this.push({ k: 'searchChar', ch }, this.typing())
    this.pause(OPEN_CMD_PAUSE)
    const hits = event.hits.slice(0, 30).map(hit => ({
      path: cellText(hit.path),
      matches: hit.matches.slice(0, 6).map(match => ({ line: match.line, text: cellText(match.text) })),
    }))
    this.push({ k: 'search', set: { hits } }, 0)
    for (let i = 1; i <= hits.length; i++) this.push({ k: 'search', set: { shown: i } }, this.speedMs * 3)
    this.pause(HUNK_PAUSE)
  }

  // Files found by name, as quick open finds them: the pattern typed into the
  // palette, the matches listed, and the palette put away.
  private scriptFindFiles(event: Extract<PlayerEvent, { type: 'findfiles' }>) {
    this.push({ k: 'palette', set: { text: '', items: [], shown: 0 } }, this.speedMs * 4)
    for (const ch of cellText(event.pattern).slice(0, 60)) this.push({ k: 'paletteChar', ch }, this.typing())
    this.pause(OPEN_CMD_PAUSE)
    const items = event.files.slice(0, 10).map(cellText)
    this.push({ k: 'palette', set: { items } }, 0)
    for (let i = 1; i <= items.length; i++) this.push({ k: 'palette', set: { shown: i } }, this.speedMs * 2)
    this.pause(HUNK_PAUSE)
    this.push({ k: 'palette', set: null })
  }

  // A commit lands in the terminal with its id and branch and the files it
  // took settle in the explorer; a push goes up with a bar, as a download comes down.
  private scriptGit(event: Extract<PlayerEvent, { type: 'git' }>) {
    if (event.commit) {
      this.push({
        k: 'termLine',
        line: { kind: 'commit', text: cellText(event.commit.message ?? ''), sha: event.commit.sha.slice(0, 7), branch: event.commit.branch },
      })
      if (event.root) this.push({ k: 'commitMark', root: event.root })
      this.pause(GIT_ADD_CMD_PAUSE)
    }
    if (event.push) {
      this.push({ k: 'termLine', line: { kind: 'progress', up: true, text: `origin/${event.push.branch}`, fraction: 0, right: 'pushing' } })
      const span = Math.min(4000, Math.max(800, event.durationMs))
      let fraction = 0
      for (let i = 1; i <= DOWNLOAD_STEPS; i++) {
        fraction = i === DOWNLOAD_STEPS ? 1 : Math.min(0.97, fraction + (Math.random() * 2) / DOWNLOAD_STEPS)
        this.push({ k: 'progress', fraction, right: `${Math.round(fraction * 100)}%` }, (span / DOWNLOAD_STEPS) * (0.4 + Math.random() * 1.2))
      }
      this.push({ k: 'progress', fraction: 1, right: words.pushed(formatDuration(event.durationMs, true)) })
      this.pause(GIT_ADD_CMD_PAUSE)
    }
  }

  // A file thrown away: the explorer walks to it, and it flies into the trash.
  private scriptDelete(event: Extract<PlayerEvent, { type: 'delete' }>) {
    this.pause(OPEN_FILE_PAUSE)
    if (event.place) {
      const folder = parentOf(event.file)
      const entries = event.place.listings[folder]
      if (entries)
        event = {
          ...event,
          place: {
            ...event.place,
            listings: { ...event.place.listings, [folder]: [...entries, { name: nameOf(event.file), dir: event.isDir }] },
          },
        }
      this.scriptNavigate(event.file, event.place!)
    }
    this.pause(OPEN_CMD_PAUSE)
    this.push({ k: 'flyStart', file: event.file }, 0)
    for (let i = 1; i <= FLY_STEPS; i++) this.push({ k: 'fly', t: i / FLY_STEPS }, this.speedMs * 1.5)
    this.push({ k: 'trash', file: event.file })
    this.plan.unlist(parentOf(event.file), nameOf(event.file))
    this.planKeep.delete(event.file)
    if (this.scriptedPath === event.path) this.scriptedPath = undefined
    this.push({ k: 'termLine', line: { kind: 'trash', text: cellText(event.path) + (event.isDir ? '/' : '') } })
    this.pause(GIT_ADD_CMD_PAUSE)
  }

  // A recording of Claude at work on one of its screens, played in the
  // editor's area frame by frame at its own pace, then let go.
  private scriptCast(event: Extract<PlayerEvent, { type: 'cast' }>) {
    if (event.frames.length === 0) {
      this.push({ k: 'castEnd', remove: event.remove }, 0)
      return
    }
    const speed = Math.round(event.speed * 10) / 10
    this.push({
      k: 'termLine',
      line: { kind: 'cast', text: `${words.screen(event.screen)} · ${event.seconds.toFixed(1)}s`, right: `×${speed}` },
    })
    this.push({ k: 'castStart', cast: { screen: event.screen, width: event.width, height: event.height, speed, seconds: event.seconds } }, 0)
    this.planScreen = 'cast'
    for (const file of event.frames) this.push({ k: 'castFrame', file }, 1000 / event.fps)
    this.pause(CHECKOUT_OUTPUT_PAUSE)
    this.push({ k: 'castEnd', remove: event.remove }, 0)
    this.planScreen = 'code'
  }

  private scriptHunks(oldLines: string[], hunks: Hunk[]) {
    // The buffer as the script leaves it, for where the cursor lands.
    const buffer = oldLines.slice()
    let cursor = 0
    let offset = 0
    for (const hunk of hunks) {
      const target = Math.max(0, hunk.oldStart - 1 + offset)
      cursor = this.scriptCursorMove(cursor, target, buffer)
      let line = target
      let i = 0
      while (i < hunk.lines.length) {
        const change = hunk.lines[i]
        if (change.kind === 'ctx') {
          if (line !== cursor) {
            this.push({ k: 'move', line, col: indentOf(change.text) })
            this.pause(CURSOR_MOVE_PAUSE)
          }
          cursor = line
          line++
          i++
          continue
        }
        // A run of removed lines and the added lines that replace them.
        const dels: string[] = []
        const adds: string[] = []
        while (i < hunk.lines.length && hunk.lines[i].kind === 'del') dels.push(hunk.lines[i++].text)
        while (i < hunk.lines.length && hunk.lines[i].kind === 'add') adds.push(hunk.lines[i++].text)
        // Line for line, a changed line is edited where it stands when most of
        // it survives; otherwise it goes and its replacement is typed.
        const pairs = Math.min(dels.length, adds.length)
        for (let k = 0; k < pairs; k++) {
          if (isSimilar(dels[k], adds[k])) this.scriptLineEdit(line, dels[k], adds[k])
          else {
            this.scriptDeleteLine(line)
            this.scriptInsertLine(line, adds[k])
          }
          buffer[line] = adds[k]
          cursor = line
          line++
        }
        for (let k = pairs; k < dels.length; k++) {
          this.scriptDeleteLine(line)
          buffer.splice(line, 1)
          cursor = line
          offset--
        }
        for (let k = pairs; k < adds.length; k++) {
          this.scriptInsertLine(line, adds[k])
          buffer.splice(line, 0, adds[k])
          cursor = line
          line++
          offset++
        }
      }
      this.pause(HUNK_PAUSE)
    }
  }

  private scriptDeleteLine(line: number) {
    this.push({ k: 'deleteLine', line })
    this.pause(DELETE_LINE_PAUSE)
  }

  private scriptInsertLine(line: number, text: string) {
    const indent = indentOf(text)
    this.push({ k: 'insertLine', line, text: text.slice(0, indent) })
    for (let col = indent; col < text.length; col++) this.push({ k: 'char', line, col, ch: text[col] }, this.typing())
    this.pause(INSERT_LINE_PAUSE)
  }

  // A line changed in place, as a person edits one: the cursor goes to the end
  // of what differs, backspaces over it, and types what replaces it.
  private scriptLineEdit(line: number, before: string, after: string) {
    let head = 0
    while (head < before.length && head < after.length && before[head] === after[head]) head++
    let tail = 0
    while (
      tail < before.length - head &&
      tail < after.length - head &&
      before[before.length - 1 - tail] === after[after.length - 1 - tail]
    )
      tail++
    const removed = before.length - head - tail
    this.push({ k: 'move', line, col: head + removed })
    this.pause(OPEN_CMD_PAUSE)
    for (let n = 0; n < removed; n++) this.push({ k: 'backspace', line, col: head + removed - n }, this.typing(0.6))
    if (removed > 0) this.pause(CURSOR_MOVE_PAUSE * 4)
    const typed = after.slice(head, after.length - tail)
    for (let n = 0; n < typed.length; n++) this.push({ k: 'char', line, col: head + n, ch: typed[n] }, this.typing())
    this.pause(INSERT_LINE_PAUSE)
  }

  private scriptCursorMove(from: number, to: number, buffer: string[]): number {
    if (from === to) return to
    const distance = Math.abs(to - from)
    const multiplier =
      distance <= 50
        ? CURSOR_MOVE_SHORT_MULTIPLIER
        : distance <= 200
          ? CURSOR_MOVE_MEDIUM_MULTIPLIER
          : CURSOR_MOVE_LONG_MULTIPLIER
    const count =
      distance <= MIN_LOG_STEPS
        ? distance
        : Math.min(MAX_SCROLL_STEPS, Math.max(MIN_LOG_STEPS, Math.floor(Math.log(distance) * LOG_SCALE_FACTOR)))
    const pause = Math.max(0.01, CURSOR_MOVE_PAUSE * multiplier)
    let last = from
    for (let i = 0; i <= count; i++) {
      const t = i / count
      const eased = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2
      const progress = Math.round(eased * distance)
      const line = from < to ? from + progress : from - progress
      if (line === last) continue
      last = line
      this.push({ k: 'move', line, col: indentOf(buffer[line]) })
      this.pause(pause)
    }
    return to
  }

  private execute(step: Step) {
    switch (step.k) {
      case 'char': {
        this.active = 'editor'
        this.marks = undefined
        const text = this.lines[step.line] ?? ''
        this.lines[step.line] = text.slice(0, step.col) + step.ch + text.slice(step.col)
        this.cursorLine = step.line
        this.cursorCol = step.col + 1
        this.highlighter.invalidate(step.line)
        break
      }
      case 'mark':
        this.active = 'editor'
        this.marks = { from: step.from, line: step.line, col: step.col }
        this.cursorLine = Math.min(step.line, this.lines.length - 1)
        this.cursorCol = step.col
        break
      case 'sidebar':
        this.sidebar = step.sidebar
        break
      case 'search':
        this.active = 'explorer'
        this.search = { query: '', hits: [], shown: 0, total: 0, ...this.search, ...step.set }
        break
      case 'searchChar':
        this.active = 'explorer'
        this.search = { query: '', hits: [], shown: 0, total: 0, ...this.search }
        this.search.query += step.ch
        break
      case 'palette':
        this.active = 'explorer'
        this.palette = step.set === null ? undefined : { text: '', items: [], shown: 0, ...this.palette, ...step.set }
        break
      case 'paletteChar':
        if (this.palette) this.palette = { ...this.palette, text: this.palette.text + step.ch }
        break
      case 'termRunning': {
        const last = this.terminal[this.terminal.length - 1]
        if (last?.kind === 'command' && last.right === undefined) last.running = true
        break
      }
      case 'commitMark':
        for (const entry of this.files.values()) if (entry.file?.startsWith(step.root + '/')) entry.committed = true
        break
      case 'flyStart': {
        const keep = new Set([...this.files.values()].flatMap(entry => (entry.file ? [entry.file] : [])))
        const rows = this.explorer.rows(keep)
        const row = rows.findIndex(r => r.path === step.file)
        this.flight = { name: nameOf(step.file), row: Math.max(0, row), depth: rows[row]?.depth ?? 1, t: 0 }
        break
      }
      case 'fly':
        if (this.flight) this.flight = { ...this.flight, t: step.t }
        break
      case 'trash': {
        this.explorer.unlist(parentOf(step.file), nameOf(step.file))
        for (const [path, entry] of [...this.files])
          if (entry.file === step.file || entry.file?.startsWith(step.file + '/')) this.files.delete(path)
        if (this.hasFile && this.currentPath && step.file.endsWith('/' + this.currentPath.replace(/^\//, ''))) {
          this.hasFile = false
          this.lines = ['']
        }
        this.flight = undefined
        this.trashed++
        break
      }
      case 'castStart':
        this.cast = step.cast
        this.castFrame = undefined
        this.setScreen('cast')
        break
      case 'castFrame':
        // The first frame mounts the picture; the rest are swapped into it.
        if (!this.castFrame) this.sceneVersion++
        this.castFrame = step.file
        break
      case 'castEnd':
        this.cast = undefined
        this.castFrame = undefined
        this.removals.push(...step.remove)
        if (this.screen === 'cast') this.setScreen('code')
        break
      case 'backspace': {
        this.active = 'editor'
        const text = this.lines[step.line] ?? ''
        this.lines[step.line] = text.slice(0, step.col - 1) + text.slice(step.col)
        this.cursorLine = step.line
        this.cursorCol = step.col - 1
        this.highlighter.invalidate(step.line)
        break
      }
      case 'insertLine':
        this.active = 'editor'
        if (this.isBlank) this.lines[0] = step.text
        else this.lines.splice(Math.min(step.line, this.lines.length), 0, step.text)
        this.isBlank = false
        this.cursorLine = step.line
        this.cursorCol = step.text.length
        this.highlighter.invalidate(step.line)
        break
      case 'deleteLine':
        this.active = 'editor'
        this.marks = undefined
        this.lines.splice(step.line, 1)
        if (this.lines.length === 0) this.lines.push('')
        this.cursorLine = Math.min(step.line, this.lines.length - 1)
        this.cursorCol = indentOf(this.lines[this.cursorLine])
        this.highlighter.invalidate(step.line)
        break
      case 'move':
        this.active = 'editor'
        this.cursorLine = Math.min(step.line, this.lines.length - 1)
        this.cursorCol = step.col
        break
      case 'pause':
        break
      case 'switchFile': {
        this.marks = undefined
        this.setScreen('code')
        this.active = 'editor'
        this.dialog = undefined
        this.hasFile = true
        this.isBlank = step.change.oldLines.length === 0
        this.lines = this.isBlank ? [''] : step.change.oldLines.slice()
        this.cursorLine = 0
        this.cursorCol = 0
        this.highlighter.setPath(step.change.path)
        this.currentPath = step.change.path
        break
      }
      case 'root':
        this.explorer.addRoot(step.root)
        break
      case 'list':
        this.explorer.list(step.dir, step.entries, step.ensure)
        break
      case 'expand':
        this.active = 'explorer'
        this.explorer.expanded.add(step.dir)
        break
      case 'select':
        this.active = 'explorer'
        this.explorer.selected = step.path
        break
      case 'screen':
        this.setScreen(step.screen)
        break
      case 'browse':
        this.active = 'explorer'
        this.browser = { ...this.browser, focus: undefined, ...step.set }
        break
      case 'boxChar':
        this.active = 'explorer'
        this.browser = { ...this.browser, query: this.browser.query + step.ch, focus: 'box' }
        break
      case 'addressChar':
        this.active = 'explorer'
        this.browser = { ...this.browser, url: this.browser.url + step.ch, focus: 'address' }
        break
      case 'image':
        this.image = step.image
        this.setScreen('image')
        this.sceneVersion++
        break
      case 'progress': {
        for (let i = this.terminal.length - 1; i >= 0; i--) {
          const line = this.terminal[i]
          if (line.kind === 'progress' && (line.fraction ?? 0) < 1) {
            line.fraction = step.fraction
            if (step.right) line.right = step.right
            break
          }
        }
        break
      }
      case 'count': {
        const known = this.files.get(step.entry.path)
        const turn = this.turn?.id
        this.files.set(
          step.entry.path,
          known
            ? { ...known, added: known.added + step.entry.added, deleted: known.deleted + step.entry.deleted, turn }
            : { ...step.entry, turn },
        )
        this.currentPath = step.entry.path
        break
      }
      case 'dialogOpen':
        this.dialog = { title: words.openFile, text: '' }
        break
      case 'dialogChar':
        if (this.dialog) this.dialog.text += step.ch
        break
      case 'termLine':
        this.active = 'terminal'
        this.addLine({ ...step.line, text: cellText(step.line.text) })
        break
      case 'termChar': {
        this.active = 'terminal'
        const last = this.terminal[this.terminal.length - 1]
        if (last?.kind === 'command' && last.right === undefined) last.text += step.ch
        else this.addLine({ kind: 'command', text: step.ch })
        break
      }
      case 'termResult': {
        // The command still waiting on its result, newest first.
        for (let i = this.terminal.length - 1; i >= 0; i--) {
          const line = this.terminal[i]
          if (line.kind === 'command' && line.right === undefined) {
            line.right = step.right
            line.ok = step.ok
            line.running = false
            break
          }
        }
        break
      }
      case 'termDone': {
        this.active = 'terminal'
        const word = this.wordFor(step.durationMs) ?? words.done
        this.addLine(
          step.aborted
            ? { kind: 'fail', text: words.interrupted }
            : { kind: 'done', text: `${word} for ${formatDuration(step.durationMs)}` },
        )
        this.addLine({ kind: 'prompt', text: '' })
        break
      }
      // A new turn keeps the session's files and the open one; only what the
      // turn is about changes.
      case 'resetTurn':
        this.turn = step.turn
        this.turnVersion++
        this.active = 'terminal'
        break
    }
    if (this.terminal.length > MAX_TERMINAL_LINES) this.terminal.splice(0, this.terminal.length - MAX_TERMINAL_LINES)
  }
}

// Logs and other output a program writes as it runs, rotated ones included.
const isLog = (path: string) => /\.(log|out|err|ansi|trace|pid|jsonl)(\.\d+)?$/i.test(path)

// Why a change is not typed out, or undefined when it is.
function untypeable(path: string, hunks: Hunk[]): string | undefined {
  if (LOCK_FILES.has(path.slice(path.lastIndexOf('/') + 1))) return words.lockFile
  if (isLog(path)) return words.logFile
  let typed = 0
  for (const hunk of hunks)
    for (const line of hunk.lines) {
      if (line.text.length > MAX_TYPED_LINE) return words.generated
      if (line.kind === 'add') typed += line.text.length
    }
  return typed > MAX_TYPED_CHARS ? words.tooLarge : undefined
}

// Whether a changed line is mostly the line it replaces: what both start and
// end with covers at least half of the longer one.
function isSimilar(a: string, b: string): boolean {
  if (!a.trim() || !b.trim()) return false
  let head = 0
  while (head < a.length && head < b.length && a[head] === b[head]) head++
  let tail = 0
  while (tail < a.length - head && tail < b.length - head && a[a.length - 1 - tail] === b[b.length - 1 - tail]) tail++
  return (head + tail) * 2 >= Math.max(a.length, b.length)
}

// Whether two addresses name the same page, ignoring scheme and trailing slash.
function sameAddress(a: string, b: string): boolean {
  const bare = (url: string) => url.replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/$/, '')
  return bare(a) === bare(b)
}

function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${Math.round(bytes)} B`
  const units = ['KB', 'MB', 'GB', 'TB']
  let value = bytes / 1024
  let unit = 0
  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024
    unit++
  }
  return `${value < 10 ? value.toFixed(1) : Math.round(value)} ${units[unit]}`
}

function formatDuration(ms: number, precise = false): string {
  if (precise && ms < 10000) return `${(ms / 1000).toFixed(1)}s`
  const s = Math.round(ms / 1000)
  if (s < 60) return `${s}s`
  const m = Math.floor(s / 60)
  return m < 60 ? `${m}m ${s % 60}s` : `${Math.floor(m / 60)}h ${m % 60}m`
}

