  types: Set<string>
  caseInsensitive?: boolean
  hashCommentNeedsSpace?: boolean
  rustLifetimes?: boolean
  macros?: boolean
  sigils?: string
  decorators?: boolean
  preprocessor?: boolean
  keysBeforeColon?: boolean
  keysBeforeEquals?: boolean
  markup?: boolean
  markdown?: boolean
